values
  ('kor', 'short', '제 입으로 부르고도 스스로 그 엄청난 돈 액수에 놀래었다.', false, true),
  ('kor', 'short', '하는 경멸히 여기는 빛이 있는 것 같았다.', false, true),
  ('kor', 'short', '아내는 불시에 후회하였다.', false, true),
  ('kor', 'short', '그 틈으로 여섯 눈이 방안을 향해 쏘았다.', false, true),
  ('kor', 'short', '하고 치성도 한두 번 드린 것이 아니다.', false, true),
  ('kor', 'short', '낼은 요보다 좀 일찍 오셔요, 하고 주먹으로 하품을 끄는 것이다.', false, true),
  ('kor', 'short', '눈에 띄는 대로 곡괭이를 잡자 대뜸 달겨들었다.', false, true),
  ('kor', 'short', '그러나 왜 그들 내객은 돈을 놓고 가나?', false, true),
  ('kor', 'short', '무명 필과 주단 바리가 두 고리짝에 꼭 찼다.', false, true),
  ('kor', 'short', '앓는 어미 곁에서 배고파 보채는 개똥이(세 살먹이)에게 죽을 사줄 수도 있다.', false, true),
  ('kor', 'short', '빌어먹을 것 되는 대로 되어라.', false, true),
  ('kor', 'short', '그러면 바람 소리였구먼.', false, true),
  ('kor', 'short', '키스''가 너무 길지 않아요.', false, true),
  ('kor', 'short', '내가 머리가 터지도록 매를 얻어맞은 것이 이 때문이다.', false, true),
  ('kor', 'short', '그리고 행길로 난 유리창을 두드리며, 이상, 하는 것이다.', false, true),
  ('kor', 'short', '남편에게 저녁을 갖다주고 딱하게 바라본다.', false, true),
  ('kor', 'short', '육신이 흐느적흐느적하도록 피로했을 때만 정신이 은화처럼 맑소.', false, true),
  ('kor', 'short', '나가거라, 냉큼 꼴 치워.', false, true),
  ('kor', 'short', '웃음 소리들은 높아졌다.', false, true),
  ('kor', 'short', '말을 하려다가 나를 곁눈으로 흘끗 보고 그만 입을 닫친다.', false, true),
  ('kor', 'short', '숨소리가 씨근씨근 한다.', false, true),
  ('kor', 'short', '그들의 머리 속에는 한결같이 ''로맨틱''한 생각이 떠올랐다.', false, true),
  ('kor', 'short', '이렇게 맹세를 하며 부랴부랴 지게를 지고 일터로 갔다.', false, true),
  ('kor', 'short', '또 무얼, 하고 좀 떠름했으나 그래도 한 달포 만에 만나니 우선 반갑다.', false, true),
  ('kor', 'short', '요즘 와서는 무턱대고 공연스리 골만 내는 남편이 역 딱하였다.', false, true),
  ('kor', 'short', '그 때 벙어리 속에는 몇 푼이나 되는지 모르겠으나 고 은화들이 꽤 들어 있었다.', false, true),
  ('kor', 'short', '물건 가지고 나꾸었나부지.', false, true),
  ('kor', 'short', '그르렁거리는 숨소리조차 들을 수 없다.', false, true),
  ('kor', 'short', '하나는 이글이글 만발한 꽃 같고 하나는 시들시들 마른 낙엽 같다.', false, true),
  ('kor', 'short', '하건만 같이 있어본 날을 헤아리면 단 일년이 될락말락 한다.', false, true),
  ('kor', 'short', '이때에 그 괴상한 소리는 땍대굴 웃었다.', false, true),
  ('kor', 'short', '하고 등을 뚜덕여 줄 사람이 누구냐.', false, true),
  ('kor', 'short', '그나마 참례 못 가는 두꺼비는 빈방에서 개 밥의 도토리로 끙끙거리고.', false, true),
  ('kor', 'short', '열흘이 썩 넘어도 산신은 깜깜 무소식이었다.', false, true),
  ('kor', 'short', '쾌감이라면 어떤 종류의 쾌감일까를 계속하여 연구하였다.', false, true),
  ('kor', 'short', '아비 어미란 말에 가슴이 터지는 것도 같았으나 제겐 아버지가 없어요.', false, true),
  ('kor', 'short', '그런데 여보게, 자네 왼몸이 어째 물독에 빠진 새앙쥐 같은가?', false, true),
  ('kor', 'short', '내가 안으로 들어갈 적에 낯선 사람들이 나를 흘끔흘끔 본다.', false, true),
  ('kor', 'short', '내가 어지간히 알아맞췄지요 하는 모양이었다.', false, true),
  ('kor', 'short', '세 처녀는 얼굴을 마주 보았다.', false, true),
  ('kor', 'short', '하고, 귀를 뒤로 잡아댕기며 마냥 우는 것이 아니냐.', false, true),
  ('kor', 'short', '오늘 밤 일도 아마 헛물켜나 보다.', false, true),
  ('kor', 'short', '오늘만 좀 해보고 고만두겠어유.', false, true),
  ('kor', 'short', '나는 내 이불을 뒤집어쓰고 이번에는 참 늘어지게 한잠 잤다.', false, true),
  ('kor', 'short', '이지러는 졌으나 보름을 갓 지난 달은 부드러운 빛을 흔붓이 흘리고 있다.', false, true),
  ('kor', 'short', '흐리고 비오는 하늘은 어둠침침하게 벌써 황혼에 가까운 듯하다.', false, true),
  ('kor', 'short', '오늘 저녁 차로 떠날 것이니까 가서 짐을 매어야지.', false, true),
  ('kor', 'short', '그 먹고 난 뒤에 괴로운 것이야 겪어본 사람이 아니면 알 수 없지.', false, true),
  ('kor', 'short', '도깨비가 났단 말인가?', false, true),
  ('kor', 'short', '장인 입에서 할아버지 소리가 나오도록 해?', false, true),
  ('kor', 'short', '그 꼴을 봐하니 가여운 생각이 안 나는 것도 아니다.', false, true),
  ('kor', 'short', '영식이는 낯이 붉어지며 가까스로 한마디하였다.', false, true),
  ('kor', 'short', '니코틴이 내 횟배 앓는 뱃속으로 스미면 머릿속에 으레 백지가 준비되는 법이오.', false, true),
  ('kor', 'short', '그 꼴에 우리들과 한몫 보자는 셈이지.', false, true),
  ('kor', 'short', '얼마만에 기차는 왔고, 수십 명이나 되는 손이 정류장으로 쏟아져 나왔다.', false, true),
  ('kor', 'short', '비단옷도 해주고 싶고 좋은 양산도 사주고 싶어요!', false, true),
  ('kor', 'short', '아니다, 다르다면 다른 점도 있다.', false, true),
  ('kor', 'short', '아무 까닭 없이 그런 편지를 받은 학생이야말로 큰 재변이었다.', false, true),
  ('kor', 'short', '나는 잠시 동안 어떻게 되는 심판인지 맥을 몰라서 그 뒷모양만 덤덤히 바라보았다.', false, true),
  ('kor', 'short', '내가 학교에 다니는 것은 혹 시험 전날 밤새는 맛에 들렸는지 모른다.', false, true),
  ('kor', 'short', '큰 줄이란 본시 산운 산을 끼고 도는 법이다.', false, true),
