  ('kor', 'short', '내가 술이 먹고 싶어서 먹었단 말이요?', false, true),
  ('kor', 'short', '스승과 제자는 조그마한 책상 하나를 새에 두고 마주앉는다.', false, true),
  ('kor', 'short', '나중에는 겨우 손톱으로 목을 따라고까지 하고, 제 아들같이 함부로 훅닥이었다.', false, true),
  ('kor', 'short', '비탈길을 얼마 올라가서야 콩밭은 놓였다.', false, true),
  ('kor', 'short', '나는 다시 눈을 감고 이불을 푹 뒤집어쓰고 낮잠을 자기에 착수하였다.', false, true),
  ('kor', 'short', '착실한 녀석인 줄 알았더니.', false, true),
  ('kor', 'short', '궂은 비는 의연히 추적추적 내린다.', false, true),
