  ('kor', 'short', '자넨 물론 아들이 늦을 걸 염려하지만 점순이루 말하면 이제 겨우 열여섯이 아닌가.', false, true),
  ('kor', 'short', '그는 어쓴 위풍을 보이며 이렇게 분부하였다.', false, true),
  ('kor', 'short', '나는 이 지느러미 수효를 헤어 보기도 하면서 굽힌 허리를 좀처럼 펴지 않았다.', false, true),
  ('kor', 'short', '모친의 친정은 원래부터 제천이었던가?', false, true),
  ('kor', 'short', '중대가리는 히히 웃고 치삼을 보며 문의하는 듯이 눈짓을 하였다.', false, true),
  ('kor', 'short', '아내는 인사를 차리느라고 이런 칭찬은 하나마 별로 부러워하는 기색이 없다.', false, true),
  ('kor', 'short', '아내는 눈만 비비고 서 있다.', false, true),
