  ('kor', 'short', '온 골목에 사람의 그림자도 볼 수 없다.', false, true),
  ('kor', 'short', '하고, 둘째 처녀도 잠오는 눈을 비비며 수상해 한다.', false, true),
  ('kor', 'short', '우리 장인님 딸이 셋이 있는데 맏딸은 재작년 가을에 시집을 갔다.', false, true),
  ('kor', 'short', '이렇게까지 몹시 몹시 미웠다.', false, true),
  ('kor', 'short', '돈이 없어서 그러는 게 아니란다.', false, true),
  ('kor', 'short', '의부와도 갈라져 제천에 있죠.', false, true),
  ('kor', 'short', '그러면 달라는 대로 줄 터이니 빨리 가요.', false, true),
  ('kor', 'short', '왜 벌써 가시려고 하셔요.', false, true),
  ('kor', 'short', '몸은 괴로와도 마음은 괴롭지 않았으니까.', false, true),
  ('kor', 'short', '이번에는 매몰스럽게 내어대는 모양.', false, true),
  ('kor', 'short', '꼭 곧이들었다면 간밤에 와서 장인님과 싸웠지 무사히 있었을 리가 없지 않은가.', false, true),
  ('kor', 'short', '줄을 찾는다고 콩밭을 통히 뒤집어놓았다.', false, true),
  ('kor', 'short', '내게 불평이 있을 리 없다.', false, true),
  ('kor', 'short', '그렇게 신통한 일이란 쉽지 않어.', false, true),
  ('kor', 'short', '일 원 오십 전은 너무 과한데.', false, true),
  ('kor', 'short', '나도 이 말을 듣고 슬쩍 돌아다보니 아내가 벌써 중문 안에 들어섰더라.', false, true),
  ('kor', 'short', '그런 보람도 없이 남편은 입맛이 없다 하며 그것을 잘 먹지도 않았었다.', false, true),
  ('kor', 'short', '그것은 묻지 않아도 사랑에 겨운 남녀의 허무러진 수작이다.', false, true),
  ('kor', 'short', '나두 종아리의 파리를 쫓는 척하고 허리를 구부리며 그 궁둥이를 콱 떼밀었다.', false, true),
  ('kor', 'short', '이윽고 남편은 아내를 부른다.', false, true),
  ('kor', 'short', '길에서 까무러치기 쉬우니까다.', false, true),
  ('kor', 'short', '뒤를 따라 장판을 달음질하려니 거슴츠레한 눈이 뜨거워질 것 같다.', false, true),
  ('kor', 'short', '그러나 빈 인력거를 털털거리며 이 우중에 돌아갈 일이 꿈밖이었다.', false, true),
  ('kor', 'short', '올 적에 사랑양반을 졸라서 돈 백 원을 얻었겠지.', false, true),
  ('kor', 'short', '보일 듯 말 듯한 그 상처로부터 좁쌀 낟 같은 핏방울이 송송 솟는다.', false, true),
  ('kor', 'short', '그러나 이 수수께끼가 풀릴 때는 왔다.', false, true),
  ('kor', 'short', '장인님은 더 약이 바짝 올라서 잡은 참 지게막대기로 내 어깨를 그냥 내려갈겼다.', false, true),
  ('kor', 'short', '오늘은 또 무슨 포악을 들을려는가.', false, true),
  ('kor', 'short', '그 속에서 수없이 먼지가 흡사 미생물처럼 난무한다.', false, true),
  ('kor', 'long', '그야말로 재수가 옴붙어서 근 열흘 동안 돈 구경도 못한 김 첨지는 십 전짜리 백통화 서 푼, 또는 다섯 푼이 찰깍하고 손바닥에 떨어질 제 거의 눈물을 흘릴 만큼 기뻤었다.', false, true),
  ('kor', 'long', '아내가 장문을 열고 무엇을 찾더니 입안말로 중얼거린다. 나는 우두커니 책상머리에 앉아서 책장만 뒤적뒤적하다가 물어 보았다. 아내가 그것을 찾아 무엇 하려는 것을 앎이라.', false, true),
  ('kor', 'long', '쥐이는 것은 이불자락뿐이다. 잠결에도 조금 실망을 아니 느낄 수 없었다. 잃은 것을 찾으려는 것처럼, 눈을 부시시 떴다. 책상 위에 머리를 쓰러뜨리고 두 손으로 그것을 움켜쥐고 있는 남편을 보았다.', false, true),
  ('kor', 'long', '괴상한 소리는 또 일어났다. 당신 같은 사내는 난 싫어요. 이번에는 매몰스럽게 내어대는 모양. 나의 천사, 나의 하늘, 나의 여왕, 나의 목숨, 나의 사랑, 나를 살려 주어요, 나를 구해 주어요.', false, true),
  ('kor', 'long', '일이 암만 바빠도 나 배 아프면 고만이니까. 아픈 사람이 누가 일을 하느냐. 파릇파릇 돋아오른 풀 한숲을 뜯어 들고 다리의 거머리를 쑥쑥 문대며 장인님의 얼굴을 쳐다보았다.', false, true),
  ('kor', 'long', '그렇게 최후의 비상 수단으로 써먹는 그 신성한 비결을 이런 누추한 행랑방에서 함부로 내굴리는 채선이의 소위를 생각하면 콧방아는 말고 빨고 있던 궐련불로 그 등어리를 지진 그것도 무리는 아닐 것이다.', false, true),
  ('kor', 'long', '고달픈 간드렛불, 맥없이 푸르끼하다. 밤과 달라서 낮엔 되우 흐릿하였다. 겉으로 황토 장벽으로 앞뒤좌우가 콕 막힌 좁직한 구뎅이. 흡사히 무덤 속같이 귀중중하다.', false, true),
  ('kor', 'long', '나는 차츰 또 외출하고 싶은 생각이 났다. 그러나 아내는 나더러 외출하지 말라고 이르는 것이다. 이 약을 날마다 먹고 그리고 가만히 누워 있으라는 것이다.', false, true),
  ('kor', 'long', '반날 동안이나 뚜벅뚜벅 걷고 장터 있는 마을에 거지 반 가까왔을 때, 거친 나귀가 한바탕 우렁차게 울면, 더구나 그것이 저녁녘이어서 등불들이 어둠 속에 깜박거릴 무렵이면, 늘 당하는 것이건만 허 생원은 변치 않고 언제든지 가슴이 뛰놀았다.', false, true),
  ('kor', 'long', '이때에 빽빽 소리가 응아 소리로 변하였다. 개똥이가 물었던 젖을 빼어놓고 운다. 운대도 온 얼굴을 찡그려 붙여서, 운다는 표정을 할 뿐이다. 응아 소리도 입에서 나는 게 아니고 마치 뱃속에서 나는 듯하였다.', false, true),
  ('kor', 'long', '인력거를 타고 얼마 아니 가서 그만 잠이 들고 말았다. 한참 자다가 잠을 깨어 보니 방 안에 벌써 남폿불이 키었는데 아내는 어느결에 왔는지 외로이 앉아 바느질을 하고 화로에서는 무엇이 끓는 소리가 보글보글하였다.', false, true),
  ('kor', 'long', '그러면서도 어디인지 분주히 돌아다닌다. 집에 들면 정신없이 무슨 책을 보기도 하고 또는 밤새도록 무엇을 쓰기도 하였다. 저러는 것이 참말 부자 방망이를 맨드는 것인가 보다'' 아내는 스스로 이렇게 해석한다.', false, true),
  ('kor', 'long', '여러 겹 주름이 잡힌 훨렁 벗겨진 이마라든지, 숱이 적어서 법대로 쪽찌거나 틀어올리지를 못하고 엉성하게 그냥 빗어넘긴 머리꼬리가 뒤통수에 염소 똥만하게 붙은 것이라든지, 벌써 늙어가는 자취를 감출 길이 없었다.', false, true),
  ('kor', 'long', '그렇다구 또 개떡이냐 하면 그런 것도 아니고, 꼭 내 아내가 돼야 할 만치 그저 툽툽하게 생긴 얼굴이다. 나보다 십년이 아래니까 올해 열여섯인데 몸은 남보다 두 살이나 덜 자랐다.', false, true),
  ('kor', 'long', '그것도 서로 눈이 맞아서 들떴다면이야 누가 뭐래랴마는 저쪽에선 나의 존재를 그리 대단히 여겨 주지 않으려는데 나만 몸이 달아서 답장 못 받는 엽서를 매일같이 석 달 동안 썼다.', false, true),
  ('kor', 'long', '굿이 풀리는지 벽이 우찔하였다. 흙이 부서져 내린다. 전날이라면 이곳에서 아내 한번 못하고 생죽음이나 안 할까 털끝까지 쭈볏할 게다. 그러나 이젠 그렇게 되고도 싶다.', false, true),
  ('kor', 'long', '낮잠은 좀처럼 오지 않았다. 대문간에 나간 아내도 좀처럼 들어오지 않았다. 그러는 동안에 흐지부지 나는 잠이 들어 버렸다. 꿈이 얼쑹덜쑹 종을 잡을 수 없는 거리의 풍경을 여전히 헤매었다.', false, true),
  ('kor', 'long', '어머니는 하는 수 없이 의부를 얻어가서 술장사를 시작했죠. 술이 고주래서 의부라고 전망나니예요. 철 들어서부터 맞기 시작한 것이 하룬들 편한 날 있었을까.', false, true),
  ('kor', 'long', '정거장까지 끌어다주고 그 깜짝 놀란 일 원 오십 전을 정말 제 손에 쥠에, 제 말마따나 십 리나 되는 길을 비를 맞아 가며 질퍽거리고 온 생각은 아니하고, 거저나 얻은 듯이 고마왔다.', false, true),
  ('kor', 'long', '그러나 아니 가는 것도 내 도리가 아닐 듯하여 하는 수 없이 두루마기를 입었다. 아내는 머뭇머뭇하며 양미간을 보일 듯 말 듯 찡그리다가 곁눈으로 살짝 나를 엿보더니 돌아서서 급히 장문을 연다.', false, true),
  ('kor', 'long', '가버렸구먼, 가버렸어! 그 구두 소리를 영구히 아니 잃으려는 것처럼 귀를 기울이고 있는 아내는 모든 것을 잃었다 하는 듯이 부르짖었다. 그 소리가 사라짐과 함께 자기의 마음도 사라지고, 정신도 사라진 듯하였다.', false, true),
  ('kor', 'long', '활동사진에 보는 것처럼 기나긴 피륙을 내리워서 하나는 위에서 당기고 하나는 밑에서 매달려 디룽디룽하면서 올라가는 정경이 있었는지 모르리라. 그들의 뺨은 후끈후끈 달았다.', false, true),
  ('kor', 'long', '남은 잘도 훤칠히들 크건만 이건 위아래가 뭉툭한 것이 내 눈에는 헐없이 감참외 같다. 참외 중에는 감참외가 제일 맛좋고 예쁘니까 말이다. 둥글고 커다란 눈은 서글서글하니 좋고 좀 지쳐 찢어졌지만 입은 밥술이나 톡톡히 먹음직하니 좋다.', false, true),
  ('kor', 'long', '광화문통 큰거리에는 목덜미로 스며드는 싸늘한 바람이 가을도 이미 늦었고 청진동 어귀로 꼽들어 길 옆 이발소를 들여다보니 여덟시 사십오분, 한 시간이 되려면 아직도 이십 분이 남았다.', false, true),
  ('kor', 'long', '이렇게 지지하게 살고 말 바에는 차라리 가로지나 세로지나 사내자식이 한번 해볼 것이다. 내일부터 우리 파보세. 빌어먹을 거 안됨 고만이지. 그러나 꽁무니에서 죽을 마시고 있던 아내가 허구리를 쿡쿡 찔렀게 망정이지 그렇지 않았더면 좀 주저할 뻔도 하였다.', false, true),
  ('kor', 'long', '나에게는 인간 사회가 스스러웠다. 생활이 스스러웠다. 모두가 서먹서먹할 뿐이었다. 아내는 하루에 두 번 세수를 한다. 나는 하루 한 번도 세수를 하지 않는다.', false, true),
  ('kor', 'long', '녀석들과 어울리다가는 한이 없어. 장판의 각다귀들이란 어른보다도 더 무서운 것들인 걸. 조 선달과 동이는 각각 제 나귀에 안장을 얹고 짐을 싣기 시작하였다.', false, true),
  ('kor', 'long', '관대한 어린 손님은 그런 말을 남기고 총총히 옷도 입고 짐도 챙기러 갈 데로 갔다. 그 학생을 태우고 나선 김 첨지의 다리는 이상하게 거뿐하였다. 달음질을 한다느니보다 거의 나는 듯하였다.', false, true),
  ('kor', 'long', '이런 곤란에 그는 근 이 년 견디어 왔건마는 나의 하는 일은 오히려 아무 보람이 없고 방 안에 놓였던 세간이 줄어 가고 장농에 찼던 옷이 거의 다 없어졌을 뿐이다.', false, true),
  ('kor', 'long', '틀렸소, 잘못 알았소. 홧증이 술을 권하는 것도 아니고, ''하이칼라''가 술을 권하는 것도 아니요. 나에게 권하는 것은 따로 있어. 마누라가, 내가 어떤 ''하이칼라''한테나 홀려 다니거나, 그 ''하이칼라''가 늘 내게 술을 권하거니 하고 근심을 했으면 그것은 헛걱정이지.', false, true),
  ('kor', 'long', '하고 또 소리를 빽 지르는 법이었다. 스승과 제자는 조그마한 책상 하나를 새에 두고 마주앉는다. 하고, 문초를 시작한다. 하고, 대답 않을 수 없다. 그러면 발신인이 누구인 것을 채쳐 묻는다.', false, true),
  ('kor', 'long', '그래야 올 갈에 벼 잘되면 너 장가 들지 않니. 그래 귀가 번쩍 띄어서 그날로 일어나서 남이 이틀 품들일 논을 혼자 삶아 놓으니까 장인님도 눈깔이 커다랗게 놀랐다.', false, true),
  ('kor', 'long', '이렇게 되면 나는 저들 치다꺼리 하러 온 것도 아니겠고 너무 밸이 상해서 한구석에 서서 담배만 뻑뻑 피우고 있자니 또 미닫이가 우람스레 열리고 이번에는 나들이옷을 입은 채 옥화가 들어온다.', false, true),
  ('kor', 'long', '하자니 역 낯이 화끈하고 모닥불이 날아든다. 그러나 그들은 어지간히 착한 사람이었다. 산신이 벗나면 죽도 글릅니다. 하고 말을 받으며 그 남편은 빙그레 웃는다.', false, true),
  ('kor', 'long', '그러나 아내는 가져가지 않는다. 나는 내가 아내 방으로 가져다 둘까 하고 생각하여 보았으나 그 즈음에는 아내의 내객이 워낙 많아서 내가 아내 방에 가 볼 기회가 도무지 없었다.', false, true),
  ('kor', 'long', '닳아 없어진 굽을 몇번이나 도려내고 새 철을 신겼는지 모른다. 굽은 벌써 더 자라나기는 틀렸고 닳아버린 철 사이로는 피가 빼짓이 흘렀다. 냄새만 맡고도 주인을 분간하였다.', false, true),
  ('kor', 'long', '울다가 울다가 목도 잠겼고 또 울 기운조차 시진한 것 같다. 입이 붙었어, 이 오라질 년! 또 대답이 없네, 정말 죽었나버이. 그러자 산 사람의 눈에서 떨어진 닭의 똥 같은 눈물이 죽은 이의 뻣뻣한 얼굴을 어룽어룽 적시었다.', false, true),
  ('kor', 'long', '무엇을 생각는지 모르게 정신을 잃고 섰다가 아내의 부르는 소리를 듣고 나는 기계적으로 고개를 돌리었다. 아내는 당목옷을 갈아입고 내 마음을 알았던지 나를 위로하는 듯이 방그레 웃는다.', false, true),
  ('kor', 'long', '그것은 제 잘못을 용서해줍시사 하는 어린애 같은 웃음이었다. 조심조심 방문을 열었다. 이불이 어째 움직움직하는 듯하였다. 나를 속이랴고 이불을 쓰고 누웠구먼.', false, true),
  ('kor', 'long', '간드러진 여자의 목소리다. 경숙씨가 좋으시다면 내야 얼마나 기쁘겠읍니까. 아아, 오직 경숙씨에게 바친 나의 타는 듯한 가슴을 인제야 아셨읍니까! 정열에 띄인 사내의 목청이 분명하였다.', false, true),
  ('kor', 'long', '아따, 밥만 많이 먹게 되면 팔자는 고만 아니냐. 헌데 한 가지 과가 있다면 가끔가다 몸이(장인님이 이걸 채신이 없이 들까분다고 하지만)너무 빨리빨리 논다.', false, true),
  ('kor', 'long', '나는 또 느물려켰구나, 생각은 했으나 성이 가셔서 갑째로 내주고 방에 들어와 보니 아까와 그 풍경이 조금도 다름없고 안에서는 여전히 동이 깨지는 소리로 게걸게걸 떠들어 댄다.', false, true),
  ('kor', 'long', '남편은 적삼이 찢어지고 얼굴에 생채기를 내었다. 그리고 두 팔을 걷고 먼 산을 향하여 묵묵히 앉았다. 수재는 흙에 박혔다 나왔는지 얼굴은커녕 귓속드리 흙투성이다.', false, true),
  ('kor', 'long', '사실은 사실대로 오해는 오해대로 그저 끝없이 발을 절뚝거리면서 세상을 걸어가면 되는 것이다. 그러나 나는 이 발길이 아내에게로 돌아가야 옳은가 이것만은 분간하기가 좀 어려웠다.', false, true),
  ('kor', 'long', '고개를 넘을 때마다 나이가 알렸다. 동이 같은 젊은 축이 그지없이 부러웠다. 땀이 등을 한바탕 쪽 씻어 내렸다. 고개 너머는 바로 개울이었다. 장마에 흘러버린 널다리가 아직도 걸리지 않은 채로 있는 까닭에 벗고 건너야 되었다.', false, true),
  ('kor', 'long', '노동으로 하여 흐른 땀이 식어지자 굶주린 창자에서, 물 흐르는 옷에서 어슬어슬 한기가 솟아나기 비롯하매 일 원 오십 전이란 돈이 얼마나 괜찮고 괴로운 것인 줄 절절히 느끼었다.', false, true),
  ('kor', 'long', '나는 더욱 쓸쓸하였다. 우리집은 천변 배다리 곁에 있고 처가는 안국동에 있어 그 거리가 꽤 멀었다. 나는 천천히 가느라고 가고 아내는 속히 오느라고 오건마는 그는 늘 뒤떨어졌었다.', false, true),
  ('kor', 'long', '이런 일은 한두 번이 아니었다. 이윽고 남편은 기막힌 듯이 웃는다. 흥 또 못 알아듣는군. 묻는 내가 그르지, 마누라야 그런 말을 알 수 있겠소. 내가 설명해 드리지.', false, true),
  ('kor', 'long', '분해서 못 견디겠다는 사람 모양으로 쌔근쌔근하며 방안을 왔다갔다하던 그는, 들어오는 학생을 잡아먹을 듯이 노리면서 한 걸음 두 걸음 코가 맞닿을 만큼 바싹 다가들어서서 딱 마주선다.', false, true),
  ('kor', 'long', '이 벼가 자라서 점순이가 먹고 좀 큰다면 모르지만 그렇지도 못한 걸 내 심어서 뭘하는 거냐. 해마다 앞으로 축 불거지는 장인님의 아랫배(가 너무 먹는 걸 모르고 냇병이라나, 그 배)를 불리기 위하여 심곤 조금도 싶지 않다.', false, true),
  ('kor', 'long', '그렇다 치면 내가 입때 옥화에게 한 것이 아니라 결국은 두꺼비한테 사랑편지를 썼구나, 하고 비로소 깨달으니 아무것도 더 듣고 싶지 않아서 발길을 돌리려니까 이게 꽉 붙잡고 내 손에 끼인 먹던 궐련을 쑥 뽑아 제 입으로 가져가며 언제 한번 찾아갈 테니 노하지 않을 테냐 묻는 것이다.', false, true),
  ('kor', 'long', '손바닥에 침을 탁 뱉고 곡괭이 자루를 한번 꼰아잡더니 쉴 줄 모른다. 등뒤에서는 흙 긁는 소리가 드윽드윽 난다. 아직도 버력을 다 못 친 모양. 이 자식이 일을 하나 시졸 하나.', false, true),
  ('kor', 'long', '그것이 그저 한없이 야속하고 슬펐다. 나는 이렇게 밖에 돈을 구하는 아무런 방법도 알지는 못했다. 나는 이불 속에서 좀 울었나 보다. 그랬더니 아내가 또 내 방에를 왔다.', false, true),
  ('kor', 'long', '달밤에는 그런 이야기가 격에 맞거든. 조 선달 편을 바라는 보았으나 물론 미안해서가 아니라 달빛에 감동하여서였다. 이지러는 졌으나 보름을 갓 지난 달은 부드러운 빛을 흔붓이 흘리고 있다.', false, true),
  ('kor', 'long', '김 첨지는 이 친구를 만난 게 어떻게 반가운지 몰랐다. 자기를 살려준 은인이나 무엇같이 고맙기도 하였다. 자네는 벌써 한잔 한 모양일세그려. 압다, 재미 안 좋다고 술 못 먹을 낸가.', false, true),
  ('kor', 'long', '그는 구두를 벗고 마루에 올라서며 나오는 웃음을 참지 못하여 벙글벙글하면서 대답을 한다. 하더니 싼 종이와 집을 벗기고 양산을 펴 보인다. 흰 비단 바탕에 두어 가지 매화를 수놓은 양산이었다.', false, true),
  ('kor', 'long', '저도 모르게 대답을 하고 급히 마루로 나왔다. 잘못 신은, 발에 아니 맞는 신을 질질 끌면서 대문으로 달렸다. 중문은 아직 잠그지도 않았고 행랑방에 사람이 없지 않지마는 으례히 깊은 잠에 떨어졌을 줄 알고 뛰어나감이었다.', false, true),
  ('kor', 'long', '그것은 다른 일이 아니라, 밤이 깊어서 새로 한 점이 되어 모든 기숙생들이 달고 곤한 잠에 떨어졌을 때 난데없는 깔깔대는 웃음과 속살속살대는 말낱이 새어 흐르는 일이었다.', false, true),
  ('kor', 'long', '이 자라야 한다는 것은 내가 아니라 내 아내가 될 점순이의 키 말이다. 내가 여기에 와서 돈 한 푼 안 받고 일하기를 삼 년 하고 꼬바기 일곱 달 동안을 했다.', false, true),
  ('kor', 'long', '올룽한 낯짝에 그 두꺼비눈을 한 서너 번 끔뻑거리다 나에게 훈계가, 너는 학생이라서 아직 화류계를 모른다, 멀리 앉아서 편지만 자꾸 띄우면 그게 뭐냐고 톡톡히 나무라더니 기생은 여학생과 달라서 그저 맞붙잡고 주물러야 정을 쏟는데, 하고 사정이 딱한 듯이 입맛을 다신다.', false, true),
  ('kor', 'long', '금도 금이면 애써 키워온 콩도 콩이었다. 그걸 보는 것은 썩 속이 아팠다. 애틋한 생각이 물밀 때 가끔 삽을 놓고 허리를 구부려서 콩잎의 흙을 털어주기도 하였다.', false, true),
  ('kor', 'long', '이네들은 문간에서 두부를 사는 것이 아니라, 미닫이를 열고 방에서 두부를 사는 것이다. 이렇게 생긴 33번지 대문에 그들 18 가구의 문패를 몰아다 붙이는 것은 의미가 없다.', false, true),
  ('kor', 'long', '길이 좁은 까닭에 세 사람은 나귀를 타고 외줄로 늘어섰다. 방울소리가 시원스럽게 딸랑딸랑 메밀 밭께로 흘러간다. 앞장선 허 생원의 이야기 소리는 꽁무니에 선 동이에게는 확적히는 안 들렸으나, 그는 그대로 개운한 제멋에 적적하지는 않았다.', false, true),
  ('kor', 'long', '얼마만에 기차는 왔고, 수십 명이나 되는 손이 정류장으로 쏟아져 나왔다. 그는 슬근슬근 그 여자의 곁으로 다가들었다. 아씨, 인력거 아니 타시랍시요? 그 여학생인지 뭔지가 한참은 매우 탯갈을 빼며 입술을 꼭 다문 채 김 첨지를 거들떠보지도 않았다.', false, true),
  ('kor', 'long', '아니 그래도 정거장에 일찍이 나가야지 만일 기차를 놓치면 오죽 기다리실라구. 재삼 만류함도 돌아보지 아니하고 그는 홀홀히 나간다. 우리는 그를 보내고 방에 들어왔다.', false, true),
  ('kor', 'long', '가느름한 손이 어둠 속에서 희게 빗장을 잡고 한참 실랑이를 한다. 밤바람이 선득하게 얼굴에 안친다. 문 밖에는 아무도 없다! 온 골목에 사람의 그림자도 볼 수 없다.', false, true),
  ('kor', 'long', '사십에 가까운 노처녀인 그는 죽은깨투성이 얼굴이 처녀다운 맛이란 약에 쓰려도 찾을 수 없을 뿐인가, 시들고 거칠고 마르고 누렇게 뜬 품이 곰팡 슬은 굴비를 생각나게 한다.', false, true),
  ('kor', 'long', '나의 생각에 장모님은 제 남편이니까 역성을 할는지도 모른다. 하고, 귀를 뒤로 잡아댕기며 마냥 우는 것이 아니냐. 그만 여기에 기운이 탁 꺾이어 나는 얼빠진 등신이 되고 말았다.', false, true),
  ('kor', 'long', '저분저분히 구는 것이 너무 성이 가셔서 대답 대신 주머니에 남았던 돈 삼십 전을 꺼내 주며 담뱃값이나 하라니까 또 골을 발끈 내더니 돈을 도로 내 양복주머니에 치뜨리고 다시 조련질을 하기 시작하는 것이 아닌가.', false, true),
  ('kor', 'long', '그는 엄지가락으로 아내의 눈물을 지워주고 그리고 나서 껑충거리며 구뎅이로 들어간다. 그 흙 속에 금이 있지요? 하고 대답하고 오늘밤에는 꼭 정녕코 꼭 달아나리라 생각하였다.', false, true),
  ('kor', 'long', '그렇다고 이런 괴이한 풍모를 차리고 이 홀에서 어물어물하는 수도 없고 에이 비를 맞으면 맞았지 하고 그냥 나서 버렸다. 대단히 선선해서 견딜 수가 없다.', false, true),
  ('kor', 'long', '꼴이 우스워 우리는 보고만 있었다우. 아이는 앙토라진 투로 소리를 치며 깔깔 웃었다. 허 생원은 모르는 결에 낯이 뜨거워졌다. 뭇 시선을 막으려고 그는 짐승의 배 앞을 가리어서지 않으면 안되었다.', false, true),
  ('kor', 'long', '그 모양은 마치 자기 집 — 곧 불행을 향하고 달려가는 제 다리를 제 힘으로는 도저히 어찌할 수 없으니 누구든지 나를 좀 잡아 다고, 구해 다고 하는 듯하였다.', false, true),
  ('kor', 'long', '친척은 다 멀지 않게 살아도 가난한 꼴을 보이기도 싫고 찾아갈 적마다 무엇을 뀌어 내라고 조르지도 아니하였건만 행여나 무슨 구차한 소리를 할까 봐서 미리 방패막이를 하고 눈살을 찌푸리는 듯하여 나는 발을 끊고 따라서 찾아오는 이도 없었다.', false, true),
  ('kor', 'long', '남편은 문득 미끄러지는 듯이 벽을 타고 내려앉는다. 그의 쭉 뻗친 발 끝에 이불자락이 저리로 밀려간다. 에그, 왜 이리 하셔요. 벗자는 옷은 아니 벗으시고.', false, true),
  ('kor', 'long', '당신 같은 사내는 난 싫어요. 하다가 제물에 자지러지게 웃는다. 나를 그렇게 사랑하셔요? 당신의 목숨같이 나를 사랑하셔요? 하고 몸을 추수리는데 그 음성은 분명 울음의 가락을 띠었다.', false, true),
  ('kor', 'long', '장인님은 앞으로 우찔근하고 싸리문께로 쓰러질 듯하다 몸을 바로 고치더니 눈총을 몹시 쏘았다. 이런 쌍년의 자식, 하곤 싶으나 남의 앞이라니 차마 못하고 섰는 그 꼴이 보기에 퍽 쟁그러웠다.', false, true),
  ('kor', 'long', '마가목은 끌리는 대로 중문 안으로 들어가며 이 자식아 몇째냐, 벌써 일곱째 이래 놓질 않았니 이 주릴 할 자식, 하고 씨근벌떡하더니 안대청에서 뭐라고 주책없이 게걸거리며 발을 구르며 이렇게 집안을 떠엎는다.', false, true),
  ('kor', 'long', '하고 빗대놓고 비양거린다. 남편은 대뜸 달겨들며 그 볼치에다 다시 올찬 황밤을 주었다. 예이, 빌어먹을 거, 이판새판이다. 아내를 와락 떠다밀어 논뚝에 제켜놓고 그 허구리를 발길로 퍽 질렀다.', false, true),
  ('kor', 'long', '거기서 얼마나 내가 오래 앉았는지 정신이 오락가락하는 중에 객이 슬며시 뜸해지면서 이 구석 저 구석 걷어치우기 시작하는 것을 보면 아마 닫는 시간이 된 모양이다.', false, true),
  ('kor', 'long', '오랫동안 아둑시니같이 눈이 어둡던 허 생원도 요번만은 동이의 왼손잡이가 눈에 띄지 않을 수 없었다. 걸음도 해깝고 방울소리가 밤 벌판에 한층 청청하게 울렸다.', false, true),
  ('kor', 'long', '이날이야말로 동소문 안에서 인력거꾼 노릇을 하는 김 첨지에게는 오래간만에도 닥친 운수 좋은 날이었다. 첫번에 삼십 전, 둘째 번에 오십 전 - 아침 댓바람에 그리 흔치 않은 일이었다.', false, true),
  ('kor', 'long', '본들 모른단 말이요. 길이 탄식을 하고 그만 쓰러졌다. 울음 소리를 떨면서 무너지는 듯이 내 얼굴에 쓰러진다. 하고는 북받쳐 나오는 울음에 말이 막히고 불덩이 같은 두 뺨이 내 얼굴을 누르며 흑흑 느끼어 운다.', false, true),
  ('kor', 'long', '내게 술을 권하는 것은 홧증도 아니고 ''하이칼라''도 아니요, 이 사회란 것이 내게 술을 권한다오. 이 조선 사회란 것이 내게 술을 권한다오. 아내는 또 알 수가 없었다.', false, true),
  ('kor', 'long', '장인님이 일어나라고 해도 내가 안 일어나니까 눈에 독이 올라서 저편으로 힝하게 가더니 지게막대기를 들고 왔다. 그리고 그걸로 내 허리를 마치 돌 떠넘기듯이 쿡 찍어서 넘기고 넘기고 했다.', false, true),
  ('kor', 'long', '그 외에는 아버지가 보내 주는 흙 묻은 돈으로 근근이 공부하는 나에게 별도리가 없고, 아, 아, 이런 때 아버지가 돈 한 뭉텅이 소포로 부쳐 줄 수 있으면, 하고 한탄이 절로 날 때 국숫집 시계가 늙은 소리로 아홉시를 울린다.', false, true),
  ('kor', 'long', '땅은 암만을 파도 지수가 없다. 이만해도 다섯 길은 훨썩 넘었으리라. 좀더 지펴야 옳을지 혹은 북으로 밀어야 옳을지, 우두머니 망설거린다. 금점 일에는 푸뜸이다.', false, true),
  ('kor', 'long', '그 것들은 아물아물하는 것이 어딘가 내 어렸을 때 동무들 이름과 비슷한 데가 있었다. 거기서 얼마나 내가 오래 앉았는지 정신이 오락가락하는 중에 객이 슬며시 뜸해지면서 이 구석 저 구석 걷어치우기 시작하는 것을 보면 아마 닫는 시간이 된 모양이다.', false, true),
  ('kor', 'long', '부락스런 녀석들이라 어쩌는 수 있어야죠. 나귀를 몹시 구는 녀석들은 그냥 두지는 않을걸. 반평생을 같이 지내온 짐승이었다. 같은 주막에서 잠자고, 같은 달빛에 젖으면서 장에서 장으로 걸어 다니는 동안에 이십 년의 세월이 사람과 짐승을 함께 늙게 하였다.', false, true),
  ('kor', 'long', '이런 말을 하며 일변 돈을 줍는다. 벽에 맞아 떨어진 돈은 다시 술 끓이는 양푼에 떨어지며 정당한 매를 맞는다는 듯이 쨍하고 울었다. 곱배기 두 잔은 또 부어질 겨를도 없이 말려가고 말았다.', false, true),
  ('kor', 'long', '그러문요, 그렇고말고요. 아직 아무도 인정해 주지 않은 무명작가인 나를 다만 저 하나가 깊이깊이 인정해 준다. 그러기에 그 강한 물질에 대한 본능적 요구도 참아 가며 오늘날까지 몹시 눈살을 찌푸리지 아니하고 나를 도와 준 것이다.', false, true),
  ('kor', 'long', '그래도 못 알아듣네그려. 본정신 가지고는 피를 토하고 죽든지, 물에 빠져 죽든지 하지, 하루라도 살 수가 없단 말이야. 술 아니 먹는다고 흉장이 막혀요?', false, true),
  ('kor', 'long', '누구를 끌어당길 듯이 두 팔을 벌리고 안경을 벗은 근시안으로 잔뜩 한 곳을 노리며 그 굴비쪽 같은 얼굴에 말할 수 없이 애원하는 표정을 짓고는 ''키스''를 기다리는 것 같이 입을 쫑긋이 내어민 채 사내의 목청을 내어가면서 아깟말을 중얼거린다.', false, true),
  ('kor', 'long', '나는 겉으로 엉, 엉, 하며 귓등으로 들었다. 뭉태는 땅을 얻어부치다가 떨어진 뒤로는 장인님만 보면 공연히 못 먹어서 으릉거린다. 꼭 곧이들었다면 간밤에 와서 장인님과 싸웠지 무사히 있었을 리가 없지 않은가.', false, true),
  ('kor', 'long', '누님이 수양딸로 사다가 가무를 가르치며 부려먹는다던 이 채선이가 자정도 되기 전에 제법 방바닥에 엎으렸을 리도 없겠고, 더구나 처음에는 몰랐던 것이나 두 사람의 입 코에서 멀건 콧물과 게거품이 뺨 밑으로 검흐르는 걸 본다면 웬만한 장난은 아닐 듯싶다.', false, true),
  ('kor', 'long', '이 밭을 풀어 논도 만들 수 있을 것이다. 눈을 감아버리고 삽의 흙을 아무렇게나 콩잎 위로 홱홱 내어던진다. 동리 노인은 뻔질 찾아와서 귀 거친 소리를 하고 하였다.', false, true),
  ('kor', 'long', '나는 저물도록 길가 시계를 들여다보고 들여다보고 하면서 또 지향 없이 거리를 방황하였다. 그러나 이날은 좀처럼 피곤하지는 않았다. 다만 시간이 좀 너무 더디게 가는 것만 같아서 안타까웠다.', false, true),
  ('kor', 'long', '자나깨나 어머니 생각뿐인데요. 허 생원의 이야기로 실심해 한 끝이라 동이의 어조는 한풀 수그러진 것이었다. 아비 어미란 말에 가슴이 터지는 것도 같았으나 제겐 아버지가 없어요.', false, true),
  ('kor', 'long', '인력거가 무거워지매 그의 몸은 이상하게도 가벼워졌고 그리고 또 인력거가 가벼워지니 몸은 다시금 무거워졌건만 이번에는 마음조차 초조해 온다. 집의 광경이 자꾸 눈앞에 어른거리어 인제 요행을 바랄 여유도 없었다.', false, true),
  ('kor', 'long', '그것도 한번 두번 말이지 장구한 세월에 어찌 늘 그럴 수가 있으랴! 말경에는 아내가 가져온 세간과 의복에 손을 대는 수밖에 없었다. 잡히고 파는 것도 나는 알은체도 아니하였다.', false, true),
  ('kor', 'long', '어찌하였든 딴 나라에는 없고 조선에만 있는 요리집 이름이어니 한다. 조선에 있어도 아니 다니면 그만이지요. 남편은 또 아까 웃음을 재우친다. 집에 있으면 아니 권하고, 밖에 나가야 권하는 줄 아는가 보아.', false, true),
  ('kor', 'long', '이 B사감이 감독하는 그 기숙사에 금년 가을 들어서 괴상한 일이 생겼다. 아니 괴상한 일이 ''생겼다''느니보다 ''발각되었다''는 것이 마땅할는지 모르리라. 왜 그런고 하면 그 괴상한 일이 언제 ''시작된'' 것은 귀신밖에 모르니까.', false, true),
  ('kor', 'long', '사실 이때만치 슬펐던 일이 또 있었는지 모른다. 밥을 먹은 뒤 지게를 지고 일터로 갈려 하다 도로 벗어던지고 바깥 마당 공석 위에 드러누워서 나는 차라리 죽느니만 같지 못하다 생각했다.', false, true),
  ('kor', 'long', '하여튼 양단간에 한 시간 후라고 시간까지 지정하고 갔을 때에는 되도록 나에게 좋은 기회를 주려는 게 틀림이 없고 이렇게 내가 옥화를 얻는다면 학교쯤은 내일 집어치워도 좋다 생각하고, 외투와 더불어 허룽허룽 거리로 나선다.', false, true),
  ('kor', 'long', '부정 타라구 왜 올라와, 요망맞은 년. 남편은 몸을 고루잡자 소리를 뻑 지르며 아내 얼뺨을 붙인다. 그는 마뜩지 않게 두덜거리며 밭으로 들어간다. 밭 한가운데다 자리를 펴고 그 위에 시루를 놓았다.', false, true),
  ('kor', 'long', '18가구에 각기 빌어 들은 송이송이 꽃들 가운데서도 내 아내가 특히 아름다운 한 떨기의 꽃으로 이 함석지붕 밑 볕 안 드는 지역에서 어디까지든지 찬란하였다.', false, true),
  ('kor', 'long', '물을 다 건넜을 때에는 도리어 서글픈 생각에 좀더 업혔으면도 하였다. 진종일 실수만 하니 웬일이요, 생원. 조 선달은 바라보며 기어코 웃음이 터졌다. 나귀 생각하다 실족을 했어.', false, true),
  ('kor', 'long', '또 한번 아내를 보며 말할 수 없는 쓸쓸한 생각이 다시금 가슴을 누른다. 딴 음식은 별로 먹지도 아니하고 못 먹는 술을 넉 잔이나 마시었다. 그래도 바늘방석에 앉은 것처럼 앉아 견딜 수가 없다.', false, true),
  ('kor', 'long', '초저녁부터 아내는 별별 생각을 다하면서 남편을 고대고대하고 있었다. 지리한 시간을 속히 보내려고 치웠던 일 가지를 또 꺼내었다. 그것조차 뜻같이 아니되었다.', false, true),
  ('kor', 'long', '하루 밤이 아니고 이틀 밤이 아닌 다음에야 그런 소리가 잠귀 밝은 기숙생의 귀에 들리기도 하였지만 잠결이라 뒷동산에 구르는 마른 잎의 노래로나, 달빛에 날개를 번뜩이며 울고 가는 기러기의 소리로나 흘러들었다.', false, true),
  ('kor', 'long', '상에는 된장찌개하고 간장 한 종지, 조밥 한 그릇, 그리고 밥보다 더 수부룩하게 담은 산나물이 한 대접, 이렇다. 나물은 점순이가 틈틈이 해오니까 두 대접이고 네 대접이고 멋대로 먹어도 좋으나 밥은 장인님이 한 사발 외엔 더 주지 말라고 해서 안된다.', false, true),
  ('kor', 'long', '혹 내 일을 잘 되게 돌보아 주다가 집안에 분란이 일고 그 끝에 이렇게 되지나 않았나 생각하면 못 할 바도 아니려니와 그렇다 하더라도 두꺼비 등뒤에 똑같은 모양으로 엎으러졌는 채선이의 꼴을 보면 어떻게 추측해 볼 길이 없다.', false, true),
  ('kor', 'long', '맞은쪽 산밑에서 벼들을 베며 기뻐하는 농꾼의 노래. 수재는 눈이 휘둥그렇게 굿문을 뛰어나오며 소리를 친다. 손에는 흙 한줌이 잔뜩 쥐었다. 하고 외마디를 뒤남기자 영식이는 수재 앞으로 살같이 달려들었다.', false, true),
  ('kor', 'long', '아내는 나를 붙잡지 않았다. 나는 벽에 기대어 앉아서 담배를 한 대 피워 물고 그리고 벼락이 떨어질 테거든 어서 떨어져라 하고 기다렸다. 그러나 벼락은 내리지 않았다.', false, true),
  ('kor', 'long', '그 꼴에 우리들과 한몫 보자는 셈이지. 동이 앞에 막아서면서부터 책망이었다. 걱정두 팔자요 하는 듯이 빤히 쳐다보는 상기된 눈망울에 부딪칠 때, 결김에 따귀를 하나 갈겨주지 않고는 배길 수 없었다.', false, true),
  ('kor', 'long', '여보게 김 첨지, 자네 문안 들어갔다 오는 모양일세그려. 돈 많이 벌었을 테니 한 잔 빨리게. 뚱뚱보는 말라깽이를 보든 맡에 부르짖었다. 그 목소리는 몸짓과 딴판으로 연하고 싹싹하였다.', false, true),
  ('kor', 'long', '그러면 아까 처형의 옷감을 볼 적에도 물론 마음속으로는 부러워하였을 것이다. 다만 표면에 드러내지 않았을 따름이다. 하는 한마디에 가슴에 숨겼던 생각을 속임 없이 나타내는구나 하였다.', false, true),
  ('kor', 'long', '그러면 바람 소리였구먼. 하고 싸늘한 뺨을 쓰다듬으며 해쭉 웃고 발길을 돌리었다. 망설거리면서도 꿈꾸는 사람 모양으로 저도 모를 사이에 마루까지 올라왔다.', false, true),
  ('kor', 'long', '기숙생에게 오는 사신을 일일이 검토하는 터이니까 그따위 편지도 물론 B여사의 손에 떨어진다. 달짝지근한 사연을 보는 족족 그는 더할 수 없이 흥분되어서 얼굴이 붉으락푸르락, 편지 든 손이 발발 떨리도록 성을 낸다.', false, true),
  ('kor', 'long', '때가 되면 장인님이 어련하랴 싶어서 군소리 없이 꾸벅꾸벅 일만 해왔다. 하고 살림도 내주고 해야 나도 좋을 것이 아니냐. 시치미를 딱 떼고 도리어 그런 소리가 나올까 봐서 지레 펄펄 뛰고 이 야단이다.', false, true),
  ('kor', 'long', '그래도 제가 아쉬운지 슬쩍 눙치어 허리춤에서 아까 내가 준 담배를 꺼내어 제 입으로 한 개를 피워 주고는 그리고 그 잔소리가 선생님을 뚝 꺾어서 당신이라 부르며 옥화가 당신을 좋아할 줄 아우?', false, true),
  ('kor', 'long', '몸이 달아서 또 온 것이었다. 봉당에 걸터앉아서 저녁상을 물끄러미 바라보더니 조당수는 몸을 훑는다는 둥 일꾼은 든든히 먹어야 한다는 둥 남들은 논을 사느니 밭을 사느니 떠드는데 요렇게 지내다 그만둘 테냐는 둥 일쩌웁게 지껄인다.', false, true),
  ('kor', 'long', '그 포우즈가 부동자세에까지 고도화할 때 감정은 딱 공급을 정지합네다. 나는 내 비범한 발육을 회고하여 세상을 보는 안목을 규정하였소. 여왕봉과 미망인— 세상의 하고 많은 여인이 본질적으로 이미 미망인이 아닌 이가 있으리까?', false, true),
  ('kor', 'long', '춥춥스럽게 날아드는 파리 떼도 장난꾼 각다귀들도 귀치않다. 얼금뱅이요 왼손잡이인 드팀전의 허 생원은 기어코 동업의 조 선달에게 나꾸어 보았다. 봉평 장에서 한번이나 흐붓하게 사본 일 있을까해.', false, true),
  ('kor', 'long', '치삼의 끄는 손을 뿌리치더니 김 첨지는 눈물이 글썽글썽한 눈으로 싱그레 웃는다. 죽기는 왜 죽어, 생때같이 살아만 있단다. 그 오라질 년이 밥을 죽이지.', false, true),
  ('kor', 'long', '아이고 형님 오셔요. 나도 반갑게 인사를 하였다. 그날 매우 욕을 보셨지요. 못 잡숫는 술을 무슨 짝에 그렇게 잡수셔요. 말을 하려다가 나를 곁눈으로 흘끗 보고 그만 입을 닫친다.', false, true),
  ('kor', 'long', '하건만 같이 있어본 날을 헤아리면 단 일년이 될락말락 한다. 거기서 대학까지 졸업을 하였다. 이 길고 긴 세월에 아내는 얼마나 괴로왔으며 외로왔으랴! 봄이면 봄, 겨울이면 겨울, 웃는 꽃을 한숨으로 맞았고 얼음 같은 베개를 뜨거운 눈물로 덥히었다.', false, true),
  ('kor', 'long', '하고 등을 뚜덕여 줄 사람이 누구냐. 나는 장인님이 너무나 고마워서 어느덧 눈물까지 났다. 인제 다시는 안그러겠어유! 이렇게 맹세를 하며 부랴부랴 지게를 지고 일터로 갔다.', false, true),
  ('kor', 'long', '아내는 아내대로의 심이 빨랐다. 시체는 금점이 판을 잡았다. 섣부르게 농사만 짓고 있다간 결국 비렁뱅이밖에는 더 못된다. 얼마 안 있으면 산이고 논이고 밭이고 할 것 없이 다 금쟁이 손에 구멍이 뚫리고 뒤집히고 뒤죽박죽이 될 것이다.', false, true),
  ('kor', 'long', '아내에게 직업이 있었던가? 나는 아내의 직업이 무엇인지 알 수 없다. 만일 아내에게 직업이 없었다면 같이 직업이 없는 나처럼 외출할 필요가 생기지 않을 것인데— 아내는 외출한다.', false, true),
  ('kor', 'long', '내일 대화 장에서가 한몫 벌어야겠네. 오늘 밤은 밤을 새서 걸어야 될걸? 절렁절렁 소리를 내며 조 선달이 그날 번 돈을 따지는 것을 보고 허 생원은 말뚝에서 넓은 휘장을 걷고 벌여놓았던 물건을 거두기 시작하였다.', false, true),
  ('kor', 'long', '그런데 이 누그러움은 안심에서 오는 게 아니요, 자기를 덮친 무서운 불행을 빈틈없이 알게 될 때가 박두한 것을 두려워하는 마음에서 오는 것이다. 그는 불행에 다닥치기 전 시간을 얼마쯤이라도 늘리려고 버르적거렸다.', false, true),
  ('kor', 'long', '하고 우리 앞에 펼쳐 놓는다. 자세히는 모르나 여하간 값 많은 품 좋은 비단일 듯하다. 무늬 없는 것, 무늬 있는 것, 회색 옥색 초록색 분홍색이 갖가지로 윤이 흐르며 색색이 빛이 나서 나는 한참 황홀하였다.', false, true),
  ('kor', 'long', '그의 눈은 하염없이 검은 밤 안개를 물끄러미 바라보고 있다. 쏠쏠한 새벽 바람이 싸늘하게 가슴에 부딪친다. 그 부딪치는 서슬에 잠 못 자고 피곤한 몸이 부서질 듯이 지긋하였다.', false, true),
  ('kor', 'long', '한번은 장인님이 헐떡헐떡 기어서 올라오더니 내 바짓가랭이를 요렇게 노리고서 단박 움켜잡고 매달렸다. 잡아먹어라, 잡아먹어! 그래두 장인님은 놓질 않더니 내가 기어이 땅바닥에 쓰러져서 거진 까무러치게 되니까 놓는다.', false, true),
  ('kor', 'long', '몇 번 고개를 흔들어 정신을 바로잡아 가지고 들여다보나 아무 효과가 없음에는 이건 공부가 아니라, 생각하고 한구석으로 책을 내던진 뒤 일어서서 들창을 열어 놓고 개운한 공기를 마셔 본다.', false, true),
  ('kor', 'long', '벌구 말구, 맘껏 먹고 맘껏 쓰고 했네. 술에 거나한 얼굴로 신껏 주적거린다. 이 밭에 금이 묻혔네 금이. 하니까, 바로 이 산 너머 큰골에 광산이 있다.', false, true),
  ('kor', 'long', '그렇던 아내의 이런 태도는 필시 그 속에 여간하지 않은 사정이 있는 듯 시피 생각이 되고 내 마음은 좀 서운했으나 그보다도 나는 좀 너무 피로해서 오늘만은 이불 속에서 아무것도 연구하지 않기로 굳게 결심하고 잠을 기다렸다.', false, true),
  ('kor', 'long', '모친의 친정은 원래부터 제천이었던가? 시원스리 말은 안 해주나 봉평이라는 것만은 들었죠. 봉평, 그래 그 아비 성은 무엇이구? 도무지 듣지를 못했으니까.', false, true),
  ('kor', 'long', '더구나 이날 이때에 이 팔십 전이라는 돈이 그에게 얼마나 유용한지 몰랐다. 컬컬한 목에 모주 한 잔도 적실 수 있거니와 그보다도 앓는 아내에게 설렁탕 한 그릇도 사다줄 수 있음이다.', false, true),
  ('kor', 'long', '그러나 낫살이 들어갈수록 그런 생각도 없어지고 집에 돌아와 아내를 겪어 보니 의외에 그에게 따뜻한 맛과 순결한 맛을 발견하였다. 이런 줄을 점점 깨닫게 될 때에 내 마음이 얼마나 행복스러웠으랴!', false, true),
  ('kor', 'long', '그는 제 남편이 이 세상에서 가장 거룩한 사람이어니 한다. 따라서 어느 뉘보다 제일 잘 될 줄 믿는다. 몽롱하나마 그의 목적이 원대하고 고상한 것도 알았다.', false, true),
  ('kor', 'long', '허지만 점순이가 아직 어리니까 더 자라야 한다는 여기에는 어째 볼 수 없이 고만 빙빙하고 만다. 이래서 나는 애최 계약이 잘못된 걸 알았다. 이태면 이태, 삼 년이면 삼 년, 기한을 딱 작정하고 일을 해야 원 할 것이다.', false, true),
  ('kor', 'long', '이렇게 독살에 숨이 차도록 두 손으로 그 등어리를 대고 꼬집어뜯더니 그래도 꼼짝 않는 데는 할 수 없는지 결국 이 자식 너 잡아먹고 나 죽는다 하고 목청이 찢어지게 발악을 치며 귓배기를 물어뜯고자 매섭게 덤벼든다.', false, true),
  ('kor', 'long', '남은 속이 바직바직 타는데 웬 뱃심이 이리도 좋아. 영식이는 살기 띤 시선으로 고개를 돌렸다. 암 말 없이 수재를 노려본다. 그제야 꾸물꾸물 바지게에 흙을 담고 등에 메고 사다리를 올라간다.', false, true),
  ('kor', 'long', '이 장난도 곧 싫증이 난다. 나의 유희심은 육체적인 데서 정신적인 데로 비약한다. 나는 거울을 내던지고 아내의 화장대 앞으로 가까이 가서 나란히 늘어 놓인 그 가지각색의 화장품 병들을 들여다본다.', false, true),
  ('kor', 'long', '보이는 곳마다 메밀 밭이어서 개울가가 어디 없이 하얀 꽃이야. 돌 밭에 벗어도 좋을 것을, 달이 너무나 밝은 까닭에 옷을 벗으러 물방앗간으로 들어가지 않았나.', false, true),
  ('kor', 'long', '한참 있다가 우리는 눈물을 씻었다. 내 속이 얼마큼 시원한 듯하였다. 그렇게 생각하실 줄은 몰랐어요. 이런 말을 하는 아내는 눈물에 불어오른 눈꺼풀을 아픈 듯이 꿈적거린다.', false, true),
  ('kor', 'long', '얌전하던 그가 술을 먹게 된 것은 무슨 일이 맘대로 아니되어 화풀이로 그러는 줄도 어렴폿이 깨달았다. 그러나 술은 노상 먹을 것이 아니다. 그러면 패가망신하고 만다.', false, true),
  ('kor', 'long', '장모님도 덤벼들어 한쪽 귀마저 뒤로 잡아채면서 또 우는 것이다. 이렇게 꼼짝도 못하게 해놓고 장인님은 지게막대기를 들어서 사뭇 내려조졌다. 그러나 나는 구태여 피하려지도 않고 암만해도 그 속 알 수 없는 점순이의 얼굴만 멀거니 들여다보았다.', false, true),
  ('kor', 'long', '전일 같으면 내가 저에게 편지를 전해 달라고 폐를 끼치는 일이 한두 번 아니라서 저를 만나면 담뱃값으로 몇 푼씩 집어 주므로 저도 나를 늘 반기는 터이련만 왜 이리 기색이 틀렸는가.', false, true),
  ('kor', 'long', '그때는 뭘 파먹고 사나. 머슴들은 짜위나 한 듯이 일하다 말고 후딱하면 금점으로들 내빼지 않는가. 일꾼이 없어서 올엔 농사를 질 수 없느니 마느니 하고 동리에서는 떠들썩하다.', false, true),
  ('kor', 'long', '그 위에다 나는 위트와 패러독스를 바둑 포석처럼 늘어놓소. 가증할 상식의 병이오. 나는 또 여인과 생활을 설계하오. 연애기법에마저 서먹서먹해진 지성의 극치를 흘깃 좀 들여다본 일이 있는, 말하자면 일종의 정신분일자말이오.', false, true),
  ('kor', 'long', '피붙이라고는 어머니 하나뿐인 걸요. 부끄러워서 말하지 않으랴 했으나 정말예요. 제천 촌에서 달도 차지 않은 아이를 낳고 어머니는 집을 쫓겨났죠. 우스운 이야기나, 그러기 때문에 지금까지 아버지 얼굴도 본 적 없고 있는 고장도 모르고 지내와요.', false, true),
  ('kor', 'long', '흐리고 비오는 하늘은 어둠침침하게 벌써 황혼에 가까운 듯하다. 창경원 앞까지 다달아서야 그는 턱에 닿은 숨을 돌리고 걸음도 늦추잡았다. 한 걸음 두 걸음 집이 가까와올수록 그의 마음조차 괴상하게 누그러웠다.', false, true),
  ('kor', 'long', '이 말을 들으매 내 마음은 말할 수 없이 만족해지며 무슨 승리자나 된 듯이 득의양양하였다. 그리고 마음속으로, ''옳다, 그렇다. 이렇게 지내는 것이 행복이다.', false, true),
  ('kor', 'long', '그래도 몸은 꿈적도 않는다. 도리어 그 개개 풀린 눈을 자려는 것처럼 스르르 감는다. 아내는 눈만 비비고 서 있다. 방으로 들어가시라니까. 이번에는 대답조차 아니한다.', false, true),
  ('kor', 'long', '뾰족한 입을 앙다물고 돋보기 너머로 쌀쌀한 눈이 노릴 때엔 기숙생들이 오싹하고 몸서리를 치리만큼 그는 엄격하고 매서웠다. 이 B여사가 질겁을 하다시피 싫어하고 미워하는 것은 소위 ''러브레터''였다.', false, true),
  ('kor', 'long', '이번엔 안 된다, 하고 대뜸 구장님한테로 판단 가자고 소맷자락을 내끌었다. 아, 이자식이 왜 이래 어른을. 안 간다구 뻗디디구 이렇게 호령은 제맘대로 하지만 장인님 제가 내 기운은 못 당한다.', false, true),
  ('kor', 'long', '그러니 옆에 섰는 나도 덤벼들어 뜯어말리지 않을 수 없고 늙은이의 근력도 얕볼 게 아니라고 비로소 깨달았을 만치 이걸 붙잡고 한참 실갱이를 할 즈음, 그 자식 죽여 버리지 그냥 둬?', false, true),
  ('kor', 'long', '그리고 그들 부부 살아가는 살림이 참으로 참으로 몹시 부러웠다. 양근댁 남편은 날마다 금점으로 감돌며 버력더미를 뒤지고 토록을 줏어온다. 그걸 온종일 장판돌에다 갈면 수가 좋으면 이삼 원, 옥아도 칠팔십 전 꼴은 매일 심이 되는 것이었다.', false, true),
  ('kor', 'long', '무슨 목적으로 아내는 나를 밤이나 낮이나 재웠어야 됐나? 나를 밤이나 낮이나 재워 놓고, 그리고 아내는 내가 자는 동안에 무슨 짓을 했나? 나를 조금씩 조금씩 죽이려던 것일까?', false, true),
  ('kor', 'long', '대화까지는 팔십 리의 밤길, 고개를 둘이나 넘고 개울을 하나 건너고 벌판과 산길을 걸어야 된다. 달은 지금 긴 산허리에 걸려 있다. 밤중을 지난 무렵인지 죽은 듯이 고요한 속에서 짐승 같은 달의 숨소리가 손에 잡힐 듯이 들리며, 콩 포기와 옥수수 잎새가 한층 달에 푸르게 젖었다.', false, true),
  ('kor', 'long', '이 사람이 정말 미쳤단 말인가. 안 죽었어, 안 죽었대도그래. 김 첨지는 홧증을 내며 확신있게 소리를 질렀으되 그 소리엔 안 죽은 것을 믿으려고 애쓰는 가락이 있었다.', false, true),
  ('kor', 'long', '처형의 남편이 이번 그 돈을 딴 뒤로는 주야 요리점과 기생집에 돌아다니더니 일전에 어떤 기생을 얻어 가지고 미쳐 날뛰며 집에만 들면 집안 사람을 들볶고 걸핏하면 처형을 친다 한다.', false, true),
  ('kor', 'long', '아내도 뒤따라 들어왔다. 할멈은 중간턱을 넘어설 제, 몇 번 혀를 차고는, 저 갈 데로 가버렸다. 벽에 엇비슷하게 기대어 있는 남편은 무엇을 생각하는 듯이 고개를 숙이고 있다.', false, true),
  ('kor', 'long', '그래도 짧은 것을 한하겠읍니다. 그것은 묻지 않아도 사랑에 겨운 남녀의 허무러진 수작이다. 감금이 지독한 이 기숙사에 이런 일이 생길 줄이야! 세 처녀는 얼굴을 마주 보았다.', false, true),
  ('kor', 'long', '그렇지만 아까 빙장님의 말씀이 올 갈에는 열일을 제치고라두 성례를 시켜주겠다 하시니 좀 고마울겐가. 빨리 가서 모붓든 거나 마저 붓게, 군소리 말구 어서 가.', false, true),
  ('kor', 'long', '저녁을 아니 먹으므로 그냥 치워버렸다. 남편의 영을 거역키 어려워 양근댁한테로 또다시 안 갈 수 없다. 그간 양식은 줄곧 꾸어다먹고 갚지도 못하였는데 또 무슨 면목으로 입을 벌릴지 난처한 노릇이었다.', false, true),
  ('kor', 'long', '그러나 나는 드디어 머리맡에 놓았던 그 벙어리에 손을 대지 않고 말았다. 내 게으름은 그런 것에 내 주의를 환기시키기도 싫었다. 아내에게 내객이 있는 날은 이불 속으로 암만 깊이 들어가도 비 오는 날만큼 잠이 잘 오지 않았다.', false, true),
  ('kor', 'long', '그 사나운 꼴 보면 맘 좋겠다. 나가거라, 냉큼 꼴 치워. 그러나 한마디도 대거리하지 않고 하염없이 나가는 꼴을 보려니, 도리어 측은히 여겨졌다. 아직두 서름서름한 사인데 너무 과하지 않았을까 하고 마음이 섬뜩해졌다.', false, true),
  ('kor', 'long', '방안에 들어서며 설렁탕을 한구석에 놓을 사이도 없이 주정군은 목청을 있는 대로 다 내어 호통을 쳤다. 그러나 발길에 채이는 건 사람의 살이 아니고 나무등걸과 같은 느낌이 있었다.', false, true),
  ('kor', 'long', '우리도 남과 같이 살아 보아야지요! 그러나 무엇에 상당한 자극만 받으면 참고 참았던 이런 소리를 하게 되는 것이다. 나도 이런 소리를 들을 적마다 ''그럴 만도 하다''는 동정심이 없지 아니하나 심사가 어쩐지 좋지 못하였다.', false, true),
  ('kor', 'long', '그의 눈에는 담박에 눈물이 쏟아질 듯하였다. 이건 왜 이래, 저리로 가! 배앝는 듯이 말을 하고 휙 뿌리친다. 남편의 발길이 뚜벅뚜벅 중문에 다다랐다. 어느덧 그 밖으로 사라졌다.', false, true),
  ('kor', 'long', '키스''가 너무 길지 않아요. 행여 남이 보면 어떻해요. 아양떠는 여자 말씨. 길수록 더욱 좋지 않아요. 나는 내 목숨이 끊어질 때까지 ''키스''를 하여도 길다고는 못하겠읍니다.', false, true),
  ('kor', 'long', '허지만 장인님이 선뜻 오냐 낼이라두 성례시켜 주마, 했으면 나도 성가신 걸 그만두었을지 모른다. 나야 이러면 때린 건 아니니까 나중에 장인 쳤다는 누명도 안 들을 터이고 얼마든지 해도 좋다.', false, true),
  ('kor', 'long', '조금만 일찍 왔더라면 좋을 걸 안됐다 생각하고 그럼 반지를 전하니까 뭐라더냐 하니까 누이가 퍽 기뻐하며 그 말이 초면인사도 없이 선물을 받는 것은 실례로운 일이매 직접 만나면 돌려보내겠다 하더란다.', false, true),
  ('kor', 'long', '아, 이 사람아, 맥적게 그건 봐 뭘해, 금을 캐자니깐. 아니야, 허리가 좀 아파서! 핀잔을 얻어먹고는 좀 열쩍었다. 하기는 금만 잘 터져나오면 이까진 콩밭쯤이야.', false, true),
  ('kor', 'long', '나는 그 단벌 다 떨어진 코르덴 양복을 걸치고 배고픈 것도 주제 사나운 것도 다 잊어버리고 활갯짓을 하면서 또 거리로 나섰다. 나서면서 나는 제발 시간이 화살 단듯해서 자정이 어서 홱 지나 버렸으면 하고 조바심을 태웠다.', false, true),
  ('kor', 'long', '닷새 만큼씩의 장날에는 달보다도 확실하게 면에서 면으로 건너간다. 고향이 청주라고 자랑 삼아 말하였으나 고향에 돌보러 간 일도 있는 것 같지는 않았다. 장에서 장으로 가는 길의 아름다운 강산이 그대로 그에게는 그리운 고향이었다.', false, true),
  ('kor', 'long', '그리고 집을 나올 제 아내의 부탁이 마음에 켕기었다. 제발 덕분에 집에 붙어있어요. 정거장까지 가잔 말을 들은 순간에 경련적으로 떠는 손, 유달리 큼직한 눈, 울 듯한 아내의 얼굴이 김 첨지의 눈앞에 어른어른하였다.', false, true),
  ('kor', 'long', '흥, 입을 옷이 없어서 망설거리는구나'' 나도 슬쩍 돌아서며 생각하였다. 우리는 서로 등지고 섰건만 그래도 아내가 거의 다 빈 장 안을 들여다보며 입을 만한 옷이 없어 눈살을 찌푸린 양이 눈앞에 선연함을 어찌할 수가 없었다.', false, true),
  ('kor', 'long', '자기의 기대는 나날이 틀려간다. 좇아서 기대에 대한 자신도 엷어간다. 더구나 수척해가는 남편의 얼굴을 볼 때에 그런 감정을 걷잡을 수 없었다. 지금 저도 모르게 흥분한 것이 또한 무리가 아니었다.', false, true),
  ('kor', 'long', '전등 불은 아직 끄지 않았는데 침대 위에는 기숙생에게 온 소위 ''러브레터''의 봉투가 너저분하게 흩어졌고 그 알맹이도 여기저기 두서없이 펼쳐진 가운데 B여사 혼자 - 아무도 없이 제 혼자 일어나 앉았다.', false, true),
  ('kor', 'long', '제 산에 불을 놓아도 징역을 가는 이땐데 남의 농사를 버려두니 죄가 얼마나 더 중한가. 그리고 자넨 정장을(사경 받으러 정장 가겠다 했다) 간대지만 그러면 괜스리 죄를 들쓰고 들어가는 걸세.', false, true),
  ('kor', 'long', '내가 모조리 처신을 잃었나, 생각하며 제물에 화가 나서 그 손을 홱 뿌리치니 이게 재미있단 듯이 한번 방긋 웃고 그러나 팔꿈치로 나의 허구리를 쿡 찌르고 나서 사람 괄시 이렇게 하는 거 아니라고 괜스레 성을 내며 토라진다.', false, true),
  ('kor', 'long', '웃어야 옳을지 울어야 옳을지. 다만 입을 반쯤 벌린 채 수재의 얼굴만 멍하니 바라본다. 이윽고 남편은 아내를 부른다. 그리고 내 뭐랬어, 그러게 해보라고 그랬지, 하고 설면설면 덤벼오는 아내가 한결 어여뻤다.', false, true),
  ('kor', 'long', '그렇기 때문에, 얼마나 지난 뒤인지 동이가 헐레벌떡거리며 황급히 부르러 왔을 때에는 마시던 잔을 그 자리에 던지고 정신없이 허덕이며 충주집을 뛰어나간 것이었다.', false, true),
  ('kor', 'long', '일 원 오십 전만 줍시요. 이 말이 저도 모를 사이에 불쑥 김 첨지의 입에서 떨어졌다. 제 입으로 부르고도 스스로 그 엄청난 돈 액수에 놀래었다. 한꺼번에 이런 금액을 불러라도 본 지가 그 얼마만인가!', false, true),
  ('kor', 'long', '그 결과 그다지 견딜성 있던 저도 요사이 와서는 때때로 쓸데없는 탄식을 하게 되었다. 하고 울음에 떨리는 가는 대답을 한다. 나는 등에 찬물을 끼얹는 듯 몸이 으쓱해지며 처량한 생각이 싸늘하게 가슴에 흘렀었다.', false, true),
  ('kor', 'long', '한 달이 지나가고 두 달이 지나간다. 공부 아니한 사람보다 조금도 다른 것이 없었다. 아니다, 다르다면 다른 점도 있다. 남은 돈벌이를 하는데 그의 남편은 도리어 집안 돈을 쓴다.', false, true),
  ('kor', 'long', '이 안에 있는 여자 애인을 보려고 학교 근처를 뒤돌고 곰돌던 사내 애인이, 타는 듯한 가슴을 걷잡다 못하여 밤이 이슥하기를 기다려 담을 뛰어 넘었는지 모르리라.', false, true),
  ('kor', 'long', '네가 세번째 사윈줄이나 아니? 이자식아, 우물에 가 빠져 죽어. 나중에는 겨우 손톱으로 목을 따라고까지 하고, 제 아들같이 함부로 훅닥이었다. 우리 장인님 딸이 셋이 있는데 맏딸은 재작년 가을에 시집을 갔다.', false, true),
  ('kor', 'long', '캄캄하게 밤은 어두웠다. 어디선가 뭇개가 요란히 짖어대인다. 남편은 진흙투성이를 하고 산에서 내려왔다. 풀이 죽어서 몸을 잘 가누지도 못하고 아랫묵에 축 늘어진다.', false, true),
  ('kor', 'long', '나는 얼마든지 사죄하여도 좋다. 그러나 종시 아내의 오해를 풀지 못하였다 하면 내가 이렇게까지 사죄하는 보람은 그럼 어디 있나? 한 시간 동안을 나는 이렇게 초조하게 굴지 않으면 안 되었다.', false, true),
  ('kor', 'long', '빚을 지기 시작하니 재산을 모을 염은 당초에 틀리고 간신히 입에 풀칠을 하러 장에서 장으로 돌아다니게 되었다. 평생 인연이 없는 것이라고 신세가 서글퍼졌다.', false, true),
  ('kor', 'long', '병이 이대도록 심해지기는 열흘 전에 조밥을 먹고 체한 때문이다. 홉뜬 눈은 조금 바루어졌건만 이슬이 맺히었다. 김 첨지의 눈시울도 뜨끈뜨끈하였다. 이 환자가 그러고도 먹는 데는 물리지 않았다.', false, true),
  ('kor', 'long', '내 밥상이 나매 아내가 밥을 먹기 시작한다. 그러면 지금껏 내 잠 깨기를 기다리고 밥을 먹지 아니하였구나 하고 오늘 처가에서 본 일을 생각하였다. 어제 일이 있은 후로 우리 사이에 무슨 벽이 생긴 듯하던 것이 그 벽이 점점 엷어져 가는 듯하며 가엾고 사랑스러운 생각이 일어났었다.', false, true),
  ('kor', 'long', '하고 마음속으로 소곤거렸다. 가만히 내려앉는다. 그 모양이 이것을 건드려서는 큰일이 나지요 하는 듯하였다. 이불을 펄쩍 쳐들었다. 비인 요가 하얗게 드러난다.', false, true),
  ('kor', 'long', '짖궂은 세째 처녀는 몸을 일으키며 이런 제의를 하였다. 쌀벌레 같은 그들의 발가락은 가장 조심성 많게 소리나는 곳을 향해서 곰실곰실 기어간다. 컴컴한 복도에 자다가 일어난 세 처녀의 흰 모양은 그림자처럼 소리없이 움직였다.', false, true),
  ('kor', 'long', '내가 다 먹고 물러섰을 때, 그릇을 챙기는데 난 깜짝 놀라지 않았느냐. 하고 혼자서 쫑알거린다. 고대 잘 내외하다가 이게 무슨 소린가, 하고 난 정신이 얼떨떨했다.', false, true),
  ('kor', 'long', '아마 노름을 나갔다가 이 급보를 받고 달려온 듯싶고 하도 그러던 차라 나는 복장이 두근거리어 나도 모르게 한걸음 앞으로 나갔으나 그는 나에게 관하여는 일체 본 척도 없다.', false, true),
  ('kor', 'long', '그리고 덤벙거리며 이리 왔다가 저리 왔다가 하였다. 제 딴은 땅속에 누운 줄맥을 어림하여 보는 맥이었다. 한참을 밭을 헤매다가 산 쪽으로 붙은 한구석에 딱 서며 손가락을 펴들고 설명한다.', false, true),
  ('kor', 'long', '아내 손이 이마에 선뜻한 것을 보면 신열이 어지간한 모양인데 약을 먹는다면 해열제를 먹어야지 하고 속생각을 하자니까 아내는 따뜻한 물에 하얀 정제약 네 개를 준다.', false, true),
  ('kor', 'long', '첫날밤이 마지막 밤이었지. 그때부터 봉평이 마음에 든 것이 반평생인들 잊을 수 있겠나. 그렇게 신통한 일이란 쉽지 않어. 항용 못난 것 얻어 새끼 낳고, 걱정 늘고 생각만 해두 진저리나지- 그러나 늙으막바지까지 장돌뱅이로 지내기도 힘드는 노릇 아닌가?', false, true),
  ('kor', 'long', '오늘 손을 태고 정거장에까지 가지 않았겠나. 갔다가 그저 오기가 안 됐데그려. 그래 전차 정류장에서 어름어름하며 손님 하나를 태울 궁리를 하지 않았나. 김 첨지는 교묘하게도 정말 꾀꼬리 같은 소리를 내었다.', false, true),
  ('kor', 'long', '싫은 생각은 조금도 없어요. 아내는 살짝 분한 빛이 눈에 비치어 물끄러미 나를 들여다본다. 오늘날까지 잘 참아 오더니 인제는 점점 기색이 달라지는걸 뭐!', false, true),
  ('kor', 'long', '왜 물을 아니 잡수셔요. 곁에서 할멈이 깨우쳤다. 하고, 그제야 주인은 한 팔을 짚고 고개를 든다. 한꺼번에 물 한 대접을 다 들이켜버렸다. 그리고는 또 쓰러진다.', false, true),
  ('kor', 'long', '하고, 둘째 처녀도 잠오는 눈을 비비며 수상해 한다. 나는 언젠가 한번 들어본 법도 하구먼. 무얼 잠 아니 오는 애들이 이야기를 하는 게지. 이때에 그 괴상한 소리는 땍대굴 웃었다.', false, true),
  ('kor', 'long', '서울엘 좀 갔다오더니 사람은 점잖아야 한다구 웃쇰이(얼른 보면 지붕 위에 앉은 제비꼬랑지 같다) 양쪽으로 뾰죽히 삐치고 그걸 애헴, 하고 늘 쓰담는 손버릇이 있다.', false, true),
  ('kor', 'long', '그 서두는 품이 가만 두면 사람 몇쯤은 넉넉히 잡아 놀 듯하므로, 이런 때에는 어머니가 말리는 법인지는 모르나 내가 고대 붙들고 힐난을 하던 안늙은이가 기급을 하여 일어나서는 영감 참으슈, 영감 참으슈, 연실 이렇게 달래며 허겁지겁 밖으로 끌고 나가기에 좋이 골도 빠진다.', false, true),
  ('kor', 'long', '그리고 캄캄한 산길을 올라간다. 비탈길을 얼마 올라가서야 콩밭은 놓였다. 전면이 우뚝한 검은 산에 둘리어 막힌 곳이었다. 가생이로 느티 대추나무들은 머리를 풀었다.', false, true),
  ('kor', 'long', '나는 늘 윗방에서나 혼자서 밥을 먹고 잠을 잤다. 밥은 너무 맛이 없었다. 반찬이 너무 엉성하였다. 나는 닭이나 강아지처럼 말없이 주는 모이를 넓적넓적 받아먹기는 했으나 내심 야속하게 생각한 적도 더러 없지 않다.', false, true),
  ('kor', 'long', '허 생원은 오늘 밤도 또 그 이야기를 끄집어내려는 것이다. 조 선달은 친구가 된 이래 귀에 못이 박히도록 들어왔다. 그렇다고 싫증은 낼 수도 없었으나 허 생원은 시치미를 떼고 되풀이할 대로는 되풀이하고야 말았다.', false, true),
  ('kor', 'long', '그르렁거리는 숨소리조차 들을 수 없다. 다만 이 무덤같은 침묵을 깨뜨리는 — 깨뜨린다느니보다 한층 더 침묵을 깊게 하고 불길하게 하는 빡빡하는 그윽한 소리, 어린애의 젖 빠는 소리가 날 뿐이다.', false, true),
  ('kor', 'long', '오늘이 장인 생신이라고 어서 오라는 말을 전한다. 참 옳지, 오늘이 이월 열엿샛날이지, 나는 깜빡 잊었어! 원 아씨는 딱도 하십니다. 어쩌면 아버님 생신을 잊으신단 말씀이요.', false, true),
  ('kor', 'long', '몸이 아플 때, 마음이 쓸쓸할 제, 얼마나 그가 그리웠으랴! 하건만 아내는 이 모든 고생을 이를 악물고 참았었다. 참을 뿐이 아니라 달게 받았었다. 그것은 남편이 돌아오기만 하면!', false, true),
  ('kor', 'long', '무슨 핑계를 하든지 기어이 못 보게 하고 만다. 친부모, 친동기간이라도 규칙이 어떠니, 상학중이니 무슨 핑계를 하든지 따돌려 보내기가 일쑤다. 이로 말미암아 학생이 동맹 휴학을 하였고 교장의 설유까지 들었건만 그래도 그 버릇은 고치려 들지 않았다.', false, true),
  ('kor', 'long', '참말이지 난 이꼴하고는 집으로 차마 못 간다. 그동안 사경 쳐내슈. 너 사위로 왔지 어디 머슴살러 왔니? 그러면 얼찐 성례를 해줘야 안하지유. 이렇게 따져나가면 언제든지 늘 나만 밑지고 만다.', false, true),
  ('kor', 'long', '이게 웬일일까 얼떨하여 떨리는 음성으로 두서너 번 불러 보니 그제야 문이 삐걱 열리고 뚱뚱한 안잠자기가 나를 쳐다보고 누구를 찾느냐 하기에 두꺼비를 보러 왔다 하니까 뾰족한 입으로 중문간방을 가리키며 행주치마로 코를 쓱 씻는 양이 긴치 않다는 표정이다.', false, true),
  ('kor', 'long', '그러면 쌀을 산다, 피륙을 끊는다, 떡을 한다, 장리를 놓는다 - 그런데 우리는 왜 늘 요 꼴인지 생각만 하여도 가슴이 메이는 듯 맥맥한 한숨이 연발을 하는 것이었다.', false, true),
  ('kor', 'long', '그날은 그 일각대문에서 아내와 아내의 남자가 이야기하고 서 있는 것을 만났다. 나는 모른 체하고 두 사람 곁을 지나서 내 방으로 들어갔다. 뒤이어 아내도 들어왔다.', false, true),
  ('kor', 'long', '늙은 주제에 암샘을 내는 셈야. 아이의 웃음소리에 허 생원은 주춤하면서 거어코 견딜 수 없어 채찍을 들더니 아이를 쫓았다. 쫓으려거든 쫓아보지. 왼손잡이가 사람을 때려.', false, true),
  ('kor', 'long', '자기를 불러 멈춘 사람이 그 학교 학생인 줄 김 첨지는 한 번 보고 짐작할 수 있었다. 아마도 그 학교 기숙사에 있는 이로 동기방학을 이용하여 귀향하려 함이리라.', false, true),
  ('kor', 'long', '그는 ''이것보다 더 좋은 것을 살 수가 있나'' 하는 뜻을 보이려고 애를 쓰며 이런 발명까지 한다. 이것도 퍽 좋은데요. 아내의 떠는 목소리가 바로 내 귀 곁에서 들린다.', false, true),
  ('kor', 'long', '하고, 할멈은 우물로 기어드는 어린애를 안으려는 모양으로 두 손을 내어민다. 할멈은 고만 가 자게. 주인은 귀치않다는 듯이 말을 한다. 이를 어찌해 하는 듯이 멀거니 서 있는 아내도, 할멈이 고만 갔으면 하였다.', false, true),
  ('kor', 'long', '소리나는 방은 어렵지 않게 찾을 수 있었다. 찾고는 나무로 깎아 세운 듯이 주춤 걸음을 멈출 만큼 그들은 놀래었다. 그런 소리의 출처야말로 자기네 방에서 몇 걸음 안 되는 사감실일 줄이야!', false, true),
  ('kor', 'long', '하고 또 얼굴이 빨개지면서 성을 내며 안으로 샐죽하니 튀들어가지 않느냐, 이때 아무도 본 사람이 없었게 망정이지 보았다면 내 얼굴이 에미 잃은 황새새끼처럼 가여 웁다 했을 것이다.', false, true),
  ('kor', 'long', '물론 그 비용은 성냥 사는 일 전까지 내가 내야 되니까 얼뜬 보기에 누가 데리고 다니는 건지 영문 모른다. 게다 즈 누님의 답장을 얻어올 테니 한번 보라고 연일 장담은 하면서도 나의 편지만 가져가고는 꿩 구워 먹은 소식이다.', false, true),
  ('kor', 'long', '벼락맞느니 벼락맞어. 영식이는 그럴 적마다 데퉁스리 쏘았다. 골김에 흙을 되는대로 내꼰지고는 침을 탁 뱉고 구뎅이로 들어간다. 그러나 마음 한구석에는 언제나 끄은하였다.', false, true),
  ('kor', 'long', '그리고 내 귀에다 대고 오늘일랑 어제보다도 늦게 돌아와도 좋다고 속삭이는 것이다. 그것은 어렵지 않다. 우선 그 돈이 무엇보다도 고맙고 반가웠다. 나는 좀 야맹증이다.', false, true),
  ('kor', 'long', '장 선 꼭 이런 날 밤이었네. 객주집 토방이란 무더워서 잠이 들어야지. 밤중은 돼서 혼자 일어나 개울가에 목욕하러 나갔지. 봉평은 지금이나 그제나 마찬가지지.', false, true),
  ('kor', 'long', '사흘 전부터 설렁탕 국물이 마시고 싶다고 남편을 졸랐다. 인제 설렁탕을 사줄 수도 있다. 앓는 어미 곁에서 배고파 보채는 개똥이(세 살먹이)에게 죽을 사줄 수도 있다.', false, true),
  ('kor', 'long', '아내는 이런 근심을 하며 밥상머리에 앉아서 고기도 뜯어 주고 생선 뼈도 추려 주었다. 이것은 다 오늘 처가에서 가져온 것이다. 나는 맛나게 밥 한 그릇을 다 먹었다.', false, true),
  ('kor', 'long', '매우 기묘한 생각이 번개같이 그의 머리에 번쩍인다. 확실히 사람의 기척이 있다. 어른에게 꾸중 모시러 가는 어린애처럼 조심조심 방문 앞에 왔다. 그리고 문간 아래로 손을 대며 하염없이 웃는다.', false, true),
  ('kor', 'long', '여학교 기숙사라면 으례히 그런 편지가 많이 오는 것이지만 학교로도 유명하고 또 아름다운 여학생이 많은 탓인지 모르되 하루에도 몇 장씩 죽느니 사느니 하는 사랑 타령이 날아들어 왔었다.', false, true),
  ('kor', 'long', '세째딸이 인제 여섯살, 적어두 열 살은 돼야 데릴사위를 할 테므로 그 동안은 죽도록 부려먹어야 된다. 그러니 인제는 속 좀 채리고 장가를 들여달라구 떼를 쓰고 나자빠져라, 이것이다.', false, true),
  ('kor', 'long', '그러나 나는 너보다는 말라깽이라도 그래도 옥화가 좋다는 것을 명백히 알려 주기 위하여 무언으로 땅에다 침 한번을 탁 뱉어 던지고 대문으로 들어서려 하니까 이게 소맷자락을 잡아당기며 선생님 저 담배 하나만 더 주세요.', false, true),
  ('kor', 'long', '금점이란 칼 물고 뜀뛰기다, 잘되면이어니와 못되면 신세만 조핀다, 이렇게 전일부터 들은 소리가 있어서였다. 그 담날도 와서 꾀송거리다 갔다. 셋째 번에는 집으로 찾아왔는데 막걸리 한 병을 손에 떡 들고 영을 피운다.', false, true),
  ('kor', 'long', '이 장난이 싫증이 나면 나는 또 아내의 손잡이 거울을 가지고 여러 가지로 논다. 거울이란 제 얼굴을 비칠 때만 실용품이다. 그 외의 경우에는 도무지 장난감인 것이다.', false, true),
  ('kor', 'long', '어머니는 말리다가 채이고 맞고 칼부림을 당하고 하니 집 꼴이 무어겠소. 열 여덟 살 때 집을 뛰쳐나서부터 이 짓이죠. 총각 낫세론 섬이 무던하다고 생각했더니 듣고 보니 딱한 신세로군.', false, true),
  ('kor', 'long', '오늘 내가 돈을 막 벌었어. 참 오늘 운수가 좋았느니. 그래 얼마를 벌었단 말인가? 삼십 원을 벌었어, 삼십 원을! 오늘 돈 산더미같이 벌었는데. 어, 이 사람 취했군, 그만두세.', false, true),
  ('kor', 'long', '가슴이 어째 답답해지며 누구하고 싸움이나 좀 해보았으면 소리껏 고함이나 질러 보았으면 실컷 울어 보았으면 하는 일종 이상한 감정이 부글부글 피어 오르며, 전신에 이가 스멀스멀 기어다니는 듯 옷이 어째 몸에 끼여 견딜 수가 없다.', false, true),
  ('kor', 'long', '나에게 ''하이칼라''는 아무 소용도 없소. 나의 소용은 술뿐이요. 하고, 긴 한숨을 내어쉰다. 물큰물큰한 술냄새가 방안에 흩어진다. 아내에게는 그 말이 너무 어려웠다.', false, true),
  ('kor', 'long', '세 처녀는 귀를 소스라쳤다. 적적한 밤 가운데 다른 파동 없는 공기는 그 수상한 말 마디를 곁에서 나는 듯이 또렷또렷이 전해 주었다. 그러면 작히 좋을까요.', false, true),
  ('kor', 'long', '사람도 아마 그런가 보다, 하고 며칠내에 부쩍 (속으로) 자란 듯싶은 점순이가 여간 반가운 것이 아니다. 우리가 구장님을 찾아갔을 때 그는 싸리문 밖에 있는 돼지우리에서 죽을 퍼주고 있었다.', false, true),
  ('kor', 'long', '이렇게까지 몹시 몹시 미웠다. 뿐만 아니라 모두가 낭패다. 논둑의 풀은 성큼 자란 채 어지러이 널려 있다. 이 기미를 알고 지주는 대로하였다. 내년부터는 농사질 생각을 말라고 발을 굴렀다.', false, true),
  ('kor', 'long', '코르덴 옷이 젖기 시작하더니 나중에는 속속들이 스며들면서 치근거린다. 비를 맞아 가면서라도 견딜 수 있는 데까지 거리를 돌아다녀서 시간을 보내려 하였으나, 인제는 선선해서 이 이상은 더 견딜 수가 없다.', false, true),
  ('kor', 'long', '이렇게까지 해서 안됐네. 내 오늘은 정신이 빠진 모양이야. 염려하실 것 없어요. 그래 모친은 아비를 찾지는 않는 눈치지? 늘 한번 만나고 싶다고는 하는데요.', false, true),
  ('kor', 'long', '눌러 곱배기 한 잔을 또 마셨다. 김 첨지의 눈은 벌써 개개 풀리기 시작하였다. 석쇠에 얹힌 떡 두 개를 숭덩숭덩 썰어서 볼을 불룩거리며 또 곱배기 두 잔을 부어라 하였다.', false, true),
  ('kor', 'long', '그것을 왜 또 사셨어요. 해쓱한 얼굴에 꽃물을 들이며 아내가 치사하는 것도 들은 체 만 체하고 처형은 또 이야기를 시작한다. 올 적에 사랑양반을 졸라서 돈 백 원을 얻었겠지.', false, true),
  ('kor', 'long', '그런 보람도 없이 남편은 입맛이 없다 하며 그것을 잘 먹지도 않았었다. 또 몇 달이 지나갔다. 인제 출입을 뚝 끊고 늘 집에 붙어있다. 걸핏하면 성을 낸다.', false, true),
  ('kor', 'long', '저 소리를 들어보아요. 아닌 밤중에 저게 무슨 소리야. 하고 첫째 처녀는 호동그래진 눈에 무서워하는 빛을 띠운다. 어젯밤에 나도 저 소리에 놀랬었어. 도깨비가 났단 말인가?', false, true),
  ('kor', 'long', '허지만 농사가 한층 바쁜 때 일을 안한다든가집으로 달아 난다든가 하면 손해죄루 그것두 징역을 가거든!(여기에 그만 정신이 번쩍 났다) 왜 요전에 삼포말서 산에 불좀 놓았다구 징역간 거 못 봤나.', false, true),
  ('kor', 'long', '머리끝이 쭈뼛하도록 나는 겁을 집어먹고 이 머리를 흔들어 보고 저 머리를 흔들어 보고 이렇게 눈이 둥그랬을 때 별안간 미닫이가 딱, 하더니 필연 옥화의 어머니리라, 얼굴 강총한 늙은이가 표독스레 들어온다.', false, true),
  ('kor', 'long', '아내는 못마땅하여 눈가에 살을 모았다. 산제 지낸다구 꿔온 것은 은제나 갚는다지유? 뚱하고 있는 남편을 향하여 말끝을 꼬부린다. 그러나 남편은 눈썹 하나 까딱하지 않는다.', false, true),
  ('kor', 'long', '그러나 내객들이 내 아내에게 돈 놓고 가는 심리며 내 아내가 내게 돈 놓고 가는 심리의 비밀을 나는 알아낸 것 같아서 여간 즐거운 것이 아니다. 나는 속으로 빙그레 웃어 보았다.', false, true),
  ('kor', 'long', '젊은 시절에는 알뜰하게 벌어 돈푼이나 모아둔 적도 있기는 있었으나, 읍내에 백중이 열린 해 호탕스럽게 놀고 투전을 하고 하여 사흘 동안에 다 털어버렸다.', false, true),
  ('kor', 'long', '중대가리는 히히 웃고 치삼을 보며 문의하는 듯이 눈짓을 하였다. 그 사품에 몇 푼 은전이 잘그랑 하며 떨어진다. 여보게 돈 떨어졌네, 왜 돈을 막 끼얹나.', false, true),
  ('kor', 'long', '그 인사하는 소리가 내 귀에는 어째 비소하는 것 같기도 하고 모욕하는 것 같기도 하여 공연히 가슴이 두근거리고 얼굴이 후끈거리었다. 그 중에 제일 내게 친숙하게 인사하는 사람이 있다.', false, true),
  ('kor', 'long', '그것이 모다 수포야. 내가 술을 먹고 싶어 먹는 게 아니야. 요사이는 좀 낫지마는 처음 배울 때에는 마누라도 아다시피 죽을 애를 썼지. 그 먹고 난 뒤에 괴로운 것이야 겪어본 사람이 아니면 알 수 없지.', false, true),
  ('kor', 'long', '에그머니 저게 웬일이냐! 첫째 처녀가 소곤거렸다. 아마 미쳤나보아, 밤중에 혼자 일어나서 왜 저리고 있을꾸. 하고, 세째 처녀는 손으로 고인 때 모르는 눈물을 씻었다.', false, true),
  ('kor', 'long', '바위 틈에서 샘물 소리밖에 안 들리는 산골짜기니까 맑은 하늘의 봄볕은 이불 속같이 따스하고 꼭 꿈꾸는 것 같다. 나는 몸이 나른하고 몸살(병을 아직 모르지만)이 날려구 그러는지 가슴이 울렁울렁하고 이랬다.', false, true),
  ('kor', 'long', '손을 내밀어 악수를 하고 어서 들어오슈, 하니까 바빠서 그럴 여유가 없다 하고 오늘 의논할 이야기가 있으니 한 시간쯤 뒤에 저의 집으로 꼭 좀 와주십시오, 한다.', false, true),
  ('kor', 'long', '그리고 시루 앞에다 공손하고 정성스레 재배를 커다랗게 한다. 우리를 살려줍시사. 산신께서 거들어주지 않으면 저희는 죽을 밖에 꼼짝 수 없읍니다유. 그는 손을 모으고 이렇게 축원하였다.', false, true),
  ('kor', 'long', '나는 감기가 들었다. 여전히 으스스 춥고 또 골치가 아프고 입에 군침이 도는 것이 씁쓸하면서 다리팔이 척 늘어져서 노곤하다. 아내는 내 머리를 쓱 짚어 보더니 약을 먹어야지 한다.', false, true),
  ('kor', 'long', '저 꼴에 제법 새끼를 얻었단 말이지. 읍내 강릉집 피마에게 말일세. 귀를 쭝긋 세우고 달랑달랑 뛰는 것이 나귀새끼같이 귀여운 것이 있을까. 그것 보러 나는 일부러 읍내를 도는 때가 있다네.', false, true),
  ('kor', 'long', '그런데 여보게, 자네 왼몸이 어째 물독에 빠진 새앙쥐 같은가? 어서 이리 들어와 말리게. 선술집은 훈훈하고 뜨뜻하였다. 마음대로 할 양이면 거기 있는 모든 먹음 먹이를 모조리 깡그리 집어삼켜도 시원치 않았다.', false, true),
  ('kor', 'long', '아내가 다시금 장문을 열고 잡힐 것을 찾을 즈음에 누가 중문을 열고 들어온다. 하는 소리가 들렸다. 아내는 급히 방문을 열고 나갔다. 그는 처가에서 부리는 할멈이었다.', false, true),
  ('kor', 'long', '남편을 붙들어 일으킬 생각이야 간절하였지마는, 할멈이 보는데 어찌 그럴 수 없는 것 같았다. 란 말이 목까지 올라왔지만 입술에서 사라지고 말았다. 마음 그윽히 할멈이 돌아가기만 기다릴 뿐이었다.', false, true),
  ('kor', 'long', '그러나 이 수수께끼가 풀릴 때는 왔다. 이때 공교롭게 한 방에 자던 학생 셋이 한꺼번에 잠을 깨었다. 첫째 처녀가 소변을 보러 일어났다가 그 소리를 듣고 둘째 처녀와 세째 처녀를 깨우고 만 것이다.', false, true),
  ('kor', 'long', '뒷생각은 못하고 뺨 한 개를 딱 때려놓고는 장인님은 무색해서 덤덤히 쓴 침만 삼킨다. 난 그속을 퍽 잘 안다. 조금 있으면 갈도 꺾어야 하고 모도 내야 하고, 한참 바쁜 때인데 나 일 안하고 우리집으로 그냥 가면 고만이니까.', false, true),
  ('kor', 'long', '가만히 눈치를 살펴보니 내가 오기 전에도 몇 번 이런 북새가 인 듯싶고 암만하여도 나 자신이 헐없이 도깨비에게 홀린 듯싶어서 손을 꽂고 멀뚱히 섰노라니까 빼꼼히 열린 미닫이 틈으로 살집 좋고 허여멀건 안잠자기의 얼굴이 남실거린다.', false, true),
  ('kor', 'long', '곡괭이는 흙벽을 퍽 찍고 다시 나간다. 수재 이름만 들어도 영식이는 이가 갈렸다. 분명히 홀딱 속은 것이다. 영식이는 본디 금전에 이력이 없었다. 그리고 흥미도 없었다.', false, true),
  ('kor', 'long', '어느덧 손수건 만해졌던 볕이 나갔는데 아내는 외출에서 돌아오지 않는다. 나는 요만 일에도 좀 피곤하였고 또 아내가 돌아오기 전에 내 방으로 가 있어야 될 것을 생각하고 그만 내 방으로 건너간 다.', false, true),
  ('kor', 'long', '마을 사람들은 거지 반 돌아간 뒤요, 팔리지 못한 나무꾼 패가 길거리에 궁싯거리고들 있으나 석유병이나 받고 고깃마리나 사면 족할 이 축들을 바라고 언제까지든지 버티고 있을 법은 없다.', false, true),
  ('kor', 'long', '그리고 병자의 움쑥 들어간 눈이 원망하는 듯이 자기를 노리는 듯하였다. 그러자 엉엉하고 우는 개똥이의 곡성을 들은 듯싶다. 언뜻 깨달으니 김 첨지는 인력거를 쥔 채 길 한복판에 엉거주춤 멈춰있지 않은가.', false, true),
  ('kor', 'long', '이번에도 별로 대단치 않은 일에 처형에게 밥상으로 냅다 갈겨 바로 눈 위에 그렇게 멍이 들었다 한다. 그것 보아 돈푼이나 있으면 다 그런 것이야. 없으면 없는 대로 살아도 의좋게 지내는 것이 행복이야요.', false, true),
  ('kor', 'long', '오늘 밤에 잘 주무시면 내일 아침에 아르켜 드리지요. 무슨 말이야, 무슨 말이야. 왜 오늘 일을 내일로 미루어. 할 말이 있거든 지금 해! 지금은 약주가 취하셨으니, 내일 약주가 깨시거든 하지요.', false, true),
  ('kor', 'long', '마는 장인님이 땅에 쓰러져서 눈에 눈물이 피잉 도는 것을 알고 좀 겁도 났다. 이 악장에 안에 있었던 장모님과 점순이가 헐레벌떡하고 단숨에 뛰어 나왔다.', false, true),
  ('kor', 'long', '그 옆에 장승같이 섰는 나에게는 시선도 돌리려지 않고 두꺼비 앞에 가 팔삭 앉아서는 도끼눈을 뜨고 대뜸 들고 들어온 장죽통으로 그 머리를 후려갈기니 팡, 하고 그 소리에 내 등이 다 선뜩하다.', false, true),
  ('kor', 'long', '코밑에는 피딱지가 말라붙었고 아직도 조금씩 피가 흘러내린다. 영식이 처를 보더니 열쩍은 모양. 고개를 돌리어 모로 떨어치며 입맛만 쩍쩍 다신다. 금을 캐라니까 밤낮 피만 내다 말라는가.', false, true),
  ('kor', 'long', '섣불리 서투른 시계를 보고 그것을 믿고 시간 전에 집에 돌아갔다가 큰 코를 다쳐서는 안 된다. 나는 한 복스에 아무것도 없는 것과 마주 앉아서 잘 끓은 커피를 마셨다.', false, true),
  ('kor', 'long', '아이들의 장난이 심한 눈치여서 땀 밴 몸뚱어리가 부들부들 떨리고 좀체 흥분이 식지 않는 모양이었다. 굴레가 벗어지고 안장도 떨어졌다. 코흘리개 한 녀석이 멀리서 소리를 쳤다.', false, true),
  ('kor', 'long', '그는 이 우중에 우장도 없이 그 먼 곳을 철벅거리고 가기가 싫었음일까? 처음 것, 둘째 것으로 그만 만족하였음일까? 아니다, 결코 아니다. 이상하게도 꼬리를 맞물고 덤비는 이 행운 앞에 조금 겁이 났음이다.', false, true),
  ('kor', 'long', '이때에 처형이 사준 신이 그의 눈에 띄었는지 (혹은 나를 꺼려 보고 싶은 것을 참았는지 모르나) 그것을 집어 들고 조심조심 펴보려다가 말고 머뭇머뭇한다.', false, true),
  ('kor', 'long', '바늘 끝이 왼손 엄지손가락 손톱 밑을 찔렀음이다. 그 손가락은 가늘게 떨고 하얀 손톱 밑으로 앵두빛 같은 피가 비친다. 그것을 볼 사이도 없이 아내는 얼른 바늘을 빼고 다른 손 엄지손가락으로 그 상처를 누르고 있다.', false, true),
  ('kor', 'long', '장인님은 원체 심청이 궂어서 그러지만 나도 저만 못하지 않게 배를 채었다. 아픈 것을 눈을 꽉 감고 넌 해라 난 재밌단 듯이 있었으나 볼기짝을 후려갈길 적에는 나도 모르는 결에 벌떡 일어나서 그 수염을 잡아챘다.', false, true),
  ('kor', 'long', '아내는 집에 돌아와 떡쌀을 담그었다. 낼은 뭘로 죽을 쑤어먹을는지. 웃목에 웅크리고 앉아서 맞은쪽에 자빠져 있는 남편을 곁눈으로 살짝 할퀴어본다. 남들은 돌아다니며 잘두 금을 줏어오련만 저 망나니 제 밭 하나를 다 버려도 금 한 톨 못 줏어오나.', false, true),
  ('kor', 'long', '비웃 굽는 내, 탕고도오랑내, 뜨물내, 비눗내. 그러나 이런 것들보다도 그들의 문패가 제일로 고개를 끄덕이게 하는 것이다. 이 18가구를 대표하는 대문이라는 것이 일각이 져서 외따로 떨어지기는 했으나, 있다.', false, true),
  ('kor', 'long', '무명 필과 주단 바리가 두 고리짝에 꼭 찼다. 멍석 위에는 천 조각이 어수선하게 남았다. 다른 축들도 벌써 거진 전들을 걷고 있었다. 약바르게 떠나는 패도 있었다.', false, true),
  ('kor', 'long', '그러자 그 돈 벌 용기가 병자에 대한 염려를 사르고 말았다. 설마 오늘 내로 어떠랴 싶었다. 무슨 일이 있더라도 제일 제이의 행운을 곱친 것보다도 오히려 갑절이 많은 이 행운을 놓칠 수 없다 하였다.', false, true),
  ('kor', 'long', '이번에도 ''그럴 만도 하다''는 동정심이 없지 아니하되 또한 불쾌한 생각을 억제키 어려웠다. 차차 될 때가 있겠지! 아내의 얼굴에 붉은빛이 짙어지며 전에 없던 흥분한 어조로 이런 말까지 하였다.', false, true),
  ('kor', 'long', '그 서슬에 넘어질 뻔한 아내는 애닯게 부르짖었다. 그러면서도 같이 따라 앉는다. 그의 손은 또 옷을 잡았다. 라고 아내는 애원을 하며, 옷을 벗기려고 애를 쓴다.', false, true),
  ('kor', 'long', '덮어놓고 딸이 자라는 대로 성례를 시켜 주마, 했으니 누가 늘 지키고 섰는 것도 아니고, 그 키가 언제 자라는지 알 수 있는가. 그리고 난 사람의 키가 무럭무럭 자라는 줄만 알았지 붙배기 키에 모로만 벌어지는 몸도 있는 것을 누가 알았으랴.', false, true),
  ('kor', 'long', '그러나 대관절 올 밭도지 벼 두 섬 반은 뭘로 해내야 좋을지. 게다 밭을 망쳤으니 자칫하면 징역을 갈는지도 모른다. 영식이가 구뎅이 안으로 들어왔을 때 동무는 땅에 주저앉아 쉬고 있었다.', false, true),
  ('kor', 'long', '그저 그러고 싶었다. 나는 게서 그냥 깊이 잠이 들었다. 잠결에도 바위틈으로 흐르는 물소리가 졸졸 하고 언제까지나 귀에 어렴풋이 들려 왔다. 내가 잠을 깨었을 때는 날이 환히 밝은 뒤다.', false, true),
  ('kor', 'long', '주막까지 부지런히들 가세나. 뜰에 불을 피우고 훗훗이 쉬어. 나귀에겐 더운 물을 끓여주고. 내일 대화장 보고는 제천이다. 오래간만에 가보고 싶어. 나귀가 걷기 시작하였을 때, 동이의 채찍은 왼손에 있었다.', false, true),
  ('kor', 'long', '그의 우글우글 살찐 얼굴에 주홍이 돋는 듯, 온 턱과 뺨을 시커멓게 구레나룻이 덮였거늘, 노르탱탱한 얼굴이 바짝 말라서 여기저기 고랑이 패고, 수염도 있대야 턱밑에만 마치 솔잎 송이를 거꾸로 붙여놓은 듯한 김 첨지의 풍채하고는 기이한 대상을 짓고 있었다.', false, true),
  ('kor', 'long', '오늘도 그가 활발하게 집에 쑥 들어오더니 신문지에 싼 기름한 것을 ''이것 봐라'' 하는 듯이 마루 위에 올려놓고 분주히 구두끈을 끄른다. 쓰던 것이 벌써 다 낡았고 또 살이 부러졌다나요.', false, true),
  ('kor', 'long', '검푸른 밤 빛이 허연 길 위에 그물그물 깃들었을 뿐이었다. 아내는 무엇에 놀란 사람 모양으로 한참 멀거니 서 있었다. 문득 급거히 대문을 닫친다. 마치 그 열린 사이로 악마나 들어올 것처럼.', false, true),
  ('kor', 'long', '마는 내 골이 난 것이 아니라 정말은 아까부터 벽 뒤 울타리 구멍으로 점순이가 우리들의 꼴을 몰래 엿보고 있었기 때문이다. 가뜩이나 말 한마디 톡톡히 못한다고 바라보는데 매까지 잠자코 맞는 걸 보면 짜장 바보로 알 게 아닌가.', false, true),
  ('kor', 'long', '그나마 참례 못 가는 두꺼비는 빈방에서 개 밥의 도토리로 끙끙거리고. 그 꼴을 봐하니 가여운 생각이 안 나는 것도 아니다. 이때까지 있는 것도 한갓 저 때문인데 가라면 못 갈 줄 아냐 싶어서 나도 약이 좀 올랐으나 그렇다고 덜렁덜렁 그대로 나오기는 어렵고.', false, true),
  ('kor', 'long', '태연무심히 담배만 뻑뻑 피는 것이다. 언제나 줄을 잡는 거야. 인제 차차 나오겠지. 흙덩이를 집어들고 골통을 내려친다. 수재는 어쿠 하고 그대로 폭 엎드린다.', false, true),
  ('kor', 'long', '그들은 밤에는 잠을 자지 않나? 나는 밤이나 낮이나 잠만 자느라고 그런 것을 알 길이 없다. 33번지 18가구의 낮은 참 조용하다. 조용한 것은 낮뿐이다.', false, true),
  ('kor', 'long', '충주집 대문에 들어서서 술좌석에서 짜장 동이를 만났을 때에는 어찌 된 서슬엔지 빨끈 화가 나버렸다. 녀석이 제법 난질꾼인데 꼴 사납다. 장돌뱅이 망신만 시키고 돌아다니누나.', false, true),
  ('kor', 'long', '또 한 잔 먹고 나서 김 첨지는 치삼의 어깨를 치며 문득 껄껄 웃는다. 그 웃음 소리가 어떻게 컸는지 술집에 있는 이의 눈은 모두 김 첨지에게로 몰리었다.', false, true),
  ('kor', 'long', '다만 이 T는 촌수가 가까운 까닭인지 자주 우리를 방문하였다. 그리고 나의 평판이 항상 좋지 못했다. T는 돈을 알고 위인이 진실해서 그 애는 돈푼이나 모을 것이야!', false, true),
  ('kor', 'long', '흐릿한 의식이 돌아옴에 따라, 남편의 어깨가 덜석덜석 움직임도 깨달았다. 흑 흑 느끼는 소리가 귀를 울린다. 아내는 정신을 바짝 차리었다. 불현듯이 몸을 일으켰다.', false, true),
  ('kor', 'long', '그런데도 미처 못 자랐다니까 이 키는 언제야 자라는 겐지 짜장 영문 모른다. 일을 좀 더 잘해야 한다든지, 혹은 밥을 많이 먹는다고 노상 걱정이니까 좀 덜 먹어야 한다든지 하면 나도 얼마든지 할 말이 많다.', false, true),
  ('kor', 'long', '이년 가랑머릴 찢어놀 년, 하고 그 머리채를 들었다가 놓았다 몇 번 그러니 제물 콧방아에 코피가 흐르는 것은 보기에 좀 심한 듯싶고 얼김에 달려들어 강선생 좀 참으십시오, 하고 그 손을 꽉 잡으니까 대뜸 당신은 누구요, 하고 눈을 똑바로 뜬다.', false, true),
  ('kor', 'long', '둘이서 파면 불과 열흘 안에 줄을 잡을 게고, 적어도 하루 서너 돈씩은 따리라. 우선 삼십만 원만 해도 얼마냐. 소를 산대도 만 필이 아니냐고. 그러나 영식이는 귀담아듣지 않았다.', false, true),
  ('kor', 'long', '그냥 그날을 그저 까닭없이 펀둥펀둥 게으르고만 있으면 만사는 그만이었던 것이다. 내 몸과 마음에 옷처럼 잘 맞는 방 속에서 뒹굴면서, 축 쳐져 있는 것은 행복이니 불행이니 하는 그런 세속적인 계산을 떠난, 가장 편리하고 안일한 말하자면 절대적인 상태인 것이다.', false, true),
  ('kor', 'long', '해가 꽤 많이 기울어진 모양이었다. 드팀전 장돌림을 시작한 지 이십 년이나 되어도 허 생원은 봉평 장을 빼논 적은 드물었다. 충주 제천 등의 이웃 군에도 가고, 멀리 영남 지방도 헤매기는 하였으나, 강릉쯤에 물건 하러 가는 외에는 처음부터 끝까지 군내를 돌아다녔다.', false, true),
  ('kor', 'long', '— 팔십 전을 손에 쥔 김 첨지의 마음은 푼푼하였다. 그러나 그의 행운은 그걸로 그치지 않았다. 땀과 빗물이 섞여 흐르는 목덜미를 기름주머니가 다 된 왜목 수건으로 닦으며, 그 학교 문을 돌아나올 때였다.', false, true),
  ('kor', 'long', '마침 내가 정신없이 무엇을 생각하고 있을 즈음에 쓸쓸하게 닫혀 있는 중문이 찌긋둥 하며 비단옷 소리가 사으락사으락 들리더니 아랫목은 내게 빼앗기고 웃목에 바느질을 하고 있던 아내가 문을 열고 나간다.', false, true),
  ('kor', 'long', '몸은 나날이 축이 나 간다. 무슨 걱정이 있는고? 아내는 따라서 근심을 하게 되었다. 하고는 그 여윈 것을 보충하려고 갖가지로 애를 썼다. 곧 될 수 있는 대로 그의 밥상에 맛난 반찬가지를 붇게 하며 또 고음 같은 것도 만들었다.', false, true),
  ('kor', 'long', '가두 좋아유, 아이구 배야! 참말 난 일 안해서 징역 가도 좋다 생각했다. 일후 아들을 낳아도 그 앞에서 바보, 바보, 이렇게 별명을 들을 테니까 오늘은 열쪽이 난대도 결정을 내고 싶었다.', false, true),
  ('kor', 'long', '에에, 변변치도 못한 사나이. 저도 모르게 얕은 한숨이 거푸 두 번을 터진다. 밤이 이슥하여 그들 양주는 떡을 하러 나왔다. 남편은 절구에 쿵쿵 빻았다.', false, true),
  ('kor', 'long', '나는 이불을 뒤집어쓰고 낮잠을 잔다. 한 번도 걷은 일이 없는 내 이부자리 는 내 몸뚱이의 일부분처럼 내게는 참 반갑다. 잠은 잘 오는 적도 있다. 그러나 또 전신이 까칫까칫하면서 영 잠이 오지 않는 적도 있다.', false, true),
  ('kor', 'long', '가스러진 목뒤 털은 주인의 머리털과도 같이 바스러지고, 개진개진 젖은 눈은 주인의 눈과 같이 눈곱을 흘렸다. 몽당비처럼 짧게 쓸리운 꼬리는, 파리를 쫓으려고 기껏 휘저어보아야 벌써 다리까지는 닿지 않았다.', false, true),
  ('kor', 'long', '그래 그는 이전에도 여러 번 해본 일이라 바로 정거장 앞 전차 정류장에서 조금 떨어지게, 사람 다니는 길과 전찻길 틈에 인력거를 세워놓고 자기는 그 근처를 빙빙 돌며 형세를 관망하기로 하였다.', false, true),
  ('kor', 'long', '하고 감격이 극하여 눈물을 흘린 일도 있었다. 이런 곤란에 그는 근 이 년 견디어 왔건마는 나의 하는 일은 오히려 아무 보람이 없고 방 안에 놓였던 세간이 줄어 가고 장농에 찼던 옷이 거의 다 없어졌을 뿐이다.', false, true),
  ('kor', 'long', '또 두어 달 지나갔다. 남편의 하는 일은 늘 한 모양이었다. 한 가지 더한 것은 때때로 깊은 한숨을 쉬는 것뿐이었다. 그리고 무슨 근심이 있는 듯이 얼굴을 펴지 않았다.', false, true),
  ('kor', 'long', '장인님은 빙장님, 해야 좋아하고 밖에 나와서 장인님, 하면 괜스리 골을 내려고 든다. 뱀두 뱀이래야 좋으냐구 창피스러우니 남 듣는 데는 제발 빙장님, 빙모님, 하라구 일상 당조심을 받아오면서 난 그것두 자꾸 잊는다.', false, true),
  ('kor', 'long', '딴은 일년 고생하고 끽 콩 몇 섬 얻어먹느니보다는 금을 캐는 것이 슬기로운 짓이다. 하루에 잘만 캔다면 한 해 줄곧 공들인 그 수확보다 훨썩 이익이다. 올 봄 보낼 제 비료값, 품삯, 빚해 빚진 칠 원 까닭에 나날이 졸리는 이판이다.', false, true),
  ('kor', 'long', '따라서 그런 한 떨기 꽃을 지키고 — 아니 그 꽃에 매어달려 사는 나라는 존재가 도무지 형언할 수 없는 거북살스러운 존재가 아닐 수 없었던 것은 물론이다.', false, true),
