  ('eng', 'short', 'I’d have done the whole thing by myself, only I didn’t want to deprive you fellows of the fun!', false, true),
  ('eng', 'short', 'Well, well, I only hope it will last.', false, true),
  ('eng', 'short', 'You’ll just pamper Anne’s vanity, Matthew, and she’s as vain as a peacock now.', false, true),
  ('eng', 'short', 'It’ll do you good and give you some stomach for your meat.', false, true),
  ('eng', 'short', 'And how odd the directions will look!', false, true),
  ('eng', 'short', 'Good night, Doctor Jo.', false, true),
  ('eng', 'short', 'How can you think, Peter, that I would be away when they came?', false, true),
  ('eng', 'short', 'The man was so surprised at this answer that he sat down to think it over.', false, true),
  ('eng', 'short', 'I wasn’t meaning to be disrespectful.', false, true),
  ('eng', 'short', 'I am The Toad, the handsome, the popular, the successful Toad!', false, true),
  ('eng', 'short', 'Let them triumph over us at a distance, and be satisfied.', false, true),
  ('eng', 'short', 'Now, then, what did you do to your hair?', false, true),
  ('eng', 'short', 'I’ve chased about th’ moor in all weathers same as th’ rabbits does.', false, true),
  ('eng', 'short', 'Which brought them back again to the beginning of the conversation.', false, true),
  ('eng', 'short', 'You’d come bringing it home under your arm without any paper, just to try me.', false, true),
  ('eng', 'short', 'Must we go indoors to write?', false, true),
  ('eng', 'short', 'I am Oz, the Great and Terrible.', false, true),
  ('eng', 'short', 'He ceased to look at her, but even then she would not let go of him.', false, true),
  ('eng', 'short', 'A real wonder, that’s what you are.', false, true),
  ('eng', 'short', 'Such doings discomposed Mr. Bennet exceedingly.', false, true),
  ('eng', 'short', 'But if it kept her from being seasick it’s a mercy I did prowl, isn’t it?', false, true),
  ('eng', 'short', 'It was perhaps well he had been prepared or he might have been startled.', false, true),
  ('eng', 'short', 'It doesn’t look like one, but it is.', false, true),
  ('eng', 'short', 'Don’t think of me at all.', false, true),
  ('eng', 'short', 'Peter came tumbling in at this minute.', false, true),
  ('eng', 'short', 'Many shops stood in the street, and Dorothy saw that everything in them was green.', false, true),
  ('eng', 'short', 'Captain, is all well?', false, true),
  ('eng', 'short', 'But you are evidently in sore trouble and distress, so I will not desert you.', false, true),
  ('eng', 'short', 'But no letter appeared, and she was completely puzzled.', false, true),
  ('eng', 'short', 'She opened her eyes and looked about her.', false, true),
  ('eng', 'short', 'She felt as if they were wondering what a little girl from India was doing in their house.', false, true),
  ('eng', 'short', 'However, everything is queer to-day.', false, true),
  ('eng', 'short', 'What do you say, Beth?', false, true),
  ('eng', 'short', 'God grant it indeed may be so!', false, true),
