  ('eng', 'long', 'Well, well, I only hope it will last. And what sort of table do they keep? Charlotte is an excellent manager, I dare say. If she is half as sharp as her mother, she is saving enough.', false, true),
  ('eng', 'long', 'Now, I’ll undress Minnie May and put her to bed and you try to find some soft flannel cloths, Diana. I’m going to give her a dose of ipecac first of all.', false, true),
  ('eng', 'long', 'His once dark, heavy locks had begun to look as if they sprang healthily from his forehead and were soft and warm with life. His lips were fuller and of a normal color.', false, true),
  ('eng', 'long', 'She said this last word two or three times over to herself, being rather proud of it: for she thought, and rightly too, that very few little girls of her age knew the meaning of it at all.', false, true),
  ('eng', 'long', 'I’ll tell you, he’ll run away. Jo was sorry for that speech the minute it was made. She meant to warn him that Laurie would not bear much restraint, and hoped he would be more forebearing with the lad.', false, true),
  ('eng', 'long', 'When he walked into the large room at Uncle''s to-day, Heidi immediately rushed forward and took hold of him, for it was for Peter she had been waiting.', false, true),
  ('eng', 'long', 'I am only a Scarecrow, stuffed with straw. Therefore I have no brains, and I come to you praying that you will put brains in my head instead of straw, so that I may become as much a man as any other in your dominions.', false, true),
  ('eng', 'long', 'They found only one hillock with a stream at its base, so that Hook had no choice; here he must establish himself and wait for just before the dawn.', false, true),
  ('eng', 'long', 'It will be your head next time, Toady! The indignant Toad swam to shore, while the stoats laughed and laughed, supporting each other, and laughed again, till they nearly had two fits—that is, one fit each, of course.', false, true),
  ('eng', 'long', 'Mrs. Gardiner and Elizabeth talked of all that had occurred during their visit, as they returned, except what had particularly interested them both.', false, true),
  ('eng', 'long', 'We had a splendid tea and then Mr. Harmon Andrews took us all for a row on the Lake of Shining Waters--six of us at a time. And Jane Andrews nearly fell overboard.', false, true),
  ('eng', 'long', 'When he held up his head and fixed his strange eyes on you it seemed as if you believed him almost in spite of yourself though he was only ten years old—going on eleven.', false, true),
  ('eng', 'long', 'In another minute the whole head appeared, and then Alice put down her flamingo, and began an account of the game, feeling very glad she had someone to listen to her.', false, true),
  ('eng', 'long', 'After these tiresome labors, she must do her lessons, which was a daily trial of every virtue she possessed. Then she was allowed one hour for exercise or play, and didn’t she enjoy it?', false, true),
  ('eng', 'long', 'Heidi sat pondering for a while; she was sure in her heart that God could help out of every trouble. She thought over her own experiences and then found her answer.', false, true),
  ('eng', 'long', 'Dorothy told the Witch all her story: how the cyclone had brought her to the Land of Oz, how she had found her companions, and of the wonderful adventures they had met with.', false, true),
  ('eng', 'long', 'Liza was in a bad temper, for she was mixing the Christmas puddings in the kitchen, and had been drawn from them, with a raisin still on her cheek, by Nana’s absurd suspicions.', false, true),
  ('eng', 'long', 'From what I can make out, as soon as the stoats, who were very nervous and jumpy already, heard the shrieks and the yells and the uproar inside the hall, some of them threw down their rifles and fled.', false, true),
  ('eng', 'long', 'Four weeks passed away, and Jane saw nothing of him. She endeavoured to persuade herself that she did not regret it; but she could no longer be blind to Miss Bingley’s inattention.', false, true),
  ('eng', 'long', 'I love Miss Stacy with my whole heart, Marilla. She is so ladylike and she has such a sweet voice. We had recitations this afternoon. I just put my whole soul into it.', false, true),
  ('eng', 'long', 'When he arrived at the Manor the servants who received him with the usual ceremony noticed that he looked better and that he did not go to the remote rooms where he usually lived attended by Pitcher.', false, true),
  ('eng', 'long', 'I wish I hadn’t mentioned Dinah! Nobody seems to like her, down here, and I’m sure she’s the best cat in the world! Oh, my dear Dinah! I wonder if I shall ever see you any more!', false, true),
  ('eng', 'long', 'They had heard from Laurie where we were to be, and came to ask us to their house, but Uncle won’t go, so we shall return the call, and see them as we can.', false, true),
  ('eng', 'long', 'So that on these occasions they generally only saw more fine streets and large houses and crowds of people; they seldom got anywhere beyond them, and grass and flowers, fir trees and mountains, were still far away.', false, true),
  ('eng', 'long', 'First there was a strip of light green silk, then a strip of dark green and then a strip of emerald green; for Oz had a fancy to make the balloon in different shades of the color about them.', false, true),
  ('eng', 'long', 'They were tied to prevent their flying away, doubled up with their knees close to their ears; and for the trussing of them the black pirate had cut a rope into nine equal pieces.', false, true),
  ('eng', 'long', 'To one in such a situation, five shillings may very well appear a large sum of money. On the other hand, it did not seem very much to get for a horse.', false, true),
  ('eng', 'long', 'Were the same fair prospect to arise at present, as had flattered them a year ago, everything, she was persuaded, would be hastening to the same vexatious conclusion.', false, true),
  ('eng', 'long', 'Well now, what are you going to do about it? Matthew asked forlornly, feeling secretly thankful that Marilla and not he had to deal with the situation.', false, true),
  ('eng', 'long', 'He did not give in. She was uplifted by a sudden feeling that he looked quite beautiful in spite of his thinness. He fixed his eyes on Ben Weatherstaff in his funny imperious way.', false, true),
  ('eng', 'long', 'This was quite a new idea to Alice, and she thought it over a little before she made her next remark. Then the eleventh day must have been a holiday?', false, true),
  ('eng', 'long', 'So Jo, feeling that her late lessons in cookery were to do her honor, went to preside over the coffeepot, while the children collected dry sticks, and the boys made a fire and got water from a spring near by.', false, true),
  ('eng', 'long', 'She has an instinct where to find the best food for herself, and so if she wants to climb higher, you follow her, and it will do the others no harm if they go too; on no account bring her back.', false, true),
  ('eng', 'long', 'But Dorothy did not know this, nor could she get away from the bright red flowers that were everywhere about; so presently her eyes grew heavy and she felt she must sit down to rest and to sleep.', false, true),
  ('eng', 'long', 'It was not really Saturday night, at least it may have been, for they had long lost count of the days; but always if they wanted to do anything special they said this was Saturday night, and then they did it.', false, true),
  ('eng', 'long', 'They were investigating one of the hummocky bits the Rat had spoken of, when suddenly the Mole tripped up and fell forward on his face with a squeal.', false, true),
  ('eng', 'long', 'Bingley of course returned with him to dinner; and in the evening Mrs. Bennet’s invention was again at work to get everybody away from him and her daughter.', false, true),
  ('eng', 'long', 'But this morning it was over. I wasn’t in a temper anymore--and it left a dreadful sort of goneness, too. I felt so ashamed of myself. But I just couldn’t think of going and telling Mrs. Lynde so.', false, true),
  ('eng', 'long', 'She drew up the blinds and opened the window itself and a great waft of fresh, scented air blew in upon her. The moor was blue and the whole world looked as if something Magic had happened to it.', false, true),
  ('eng', 'long', 'For instance, suppose it were nine o’clock in the morning, just time to begin lessons: you’d only have to whisper a hint to Time, and round goes the clock in a twinkling!', false, true),
  ('eng', 'long', 'No notice was taken of Amy’s flight, except by her mates, but the sharp-eyed demoiselles discovered that Mr. Davis was quite benignant in the afternoon, also unusually nervous.', false, true),
  ('eng', 'long', 'There would be plenty of room for them in the large house, and then how astonished and delighted Clara would be when she saw the sweet little kittens.', false, true),
  ('eng', 'long', 'And then they scampered in all directions, for Toto had awakened from his sleep, and seeing all these mice around him he gave one bark of delight and jumped right into the middle of the group.', false, true),
  ('eng', 'long', 'Mrs. Darling loved to have everything just so, and Mr. Darling had a passion for being exactly like his neighbours; so, of course, they had a nurse.', false, true),
  ('eng', 'long', 'Mole’s face-beamed at the sight of all these objects so dear to him, and he hurried Rat through the door, lit a lamp in the hall, and took one glance round his old home.', false, true),
  ('eng', 'long', 'Yes, indeed; his friends may well rejoice in his having met with one of the very few sensible women who would have accepted him, or have made him happy if they had.', false, true),
  ('eng', 'long', 'It’ll ruin her teeth and stomach. There, there, child, don’t look so dismal. You can eat those, since Matthew has gone and got them. He’d better have brought you peppermints.', false, true),
  ('eng', 'long', 'The sun was shining and a little wind was blowing—not a rough wind, but one which came in delightful little gusts and brought a fresh scent of newly turned earth with it.', false, true),
  ('eng', 'long', 'This seemed to Alice a good opportunity for making her escape; so she set off at once, and ran till she was quite tired and out of breath, and till the puppy’s bark sounded quite faint in the distance.', false, true),
  ('eng', 'long', 'She enjoyed herself very much that evening, for she danced to her heart’s content. Everyone was very kind, and she had three compliments. Annie made her sing, and some one said she had a remarkably fine voice.', false, true),
  ('eng', 'long', 'When all three had got back to their old quarters Heidi ran and brought forward the bag, and proceeded to fulfil her promise, for her threat of the morning had been concerned with Peter''s dinner.', false, true),
  ('eng', 'long', 'They now came upon more and more of the big scarlet poppies, and fewer and fewer of the other flowers; and soon they found themselves in the midst of a great meadow of poppies.', false, true),
  ('eng', 'long', 'Of course Mrs. Darling said at once that she would have them; but Mr. Darling was curiously depressed, and they saw that he considered six a rather large number.', false, true),
  ('eng', 'long', 'The Toad, having finished his breakfast, picked up a stout stick and swung it vigorously, belabouring imaginary animals. I’ll learn ’em to steal my house!', false, true),
  ('eng', 'long', 'There is some sense in what he says about the girls, however; and, if he is disposed to make them any amends, I shall not be the person to discourage him.', false, true),
  ('eng', 'long', 'What are you taking all those things home for, Anne? Diana wanted to know, as soon as they were out on the road. She had not dared to ask the question before.', false, true),
  ('eng', 'long', 'She went into the first kitchen-garden and found Ben Weatherstaff working there with two other gardeners. The change in the weather seemed to have done him good.', false, true),
  ('eng', 'long', 'Alice opened the door and found that it led into a small passage, not much larger than a rat-hole: she knelt down and looked along the passage into the loveliest garden you ever saw.', false, true),
  ('eng', 'long', 'She remembered that Laurie never spoke voluntarily of Jo, she recalled the shadow on his face just now, the change in his character, and the wearing of the little old ring which was no ornament to a handsome hand.', false, true),
  ('eng', 'long', 'Her eyes were alight with joy. And now she turned to her friend to see if he too were enjoying the beauty. The doctor had been sitting thoughtfully gazing around him.', false, true),
  ('eng', 'long', 'The Tin Woodman was about to reply when he heard a low growl, and turning his head (which worked beautifully on hinges) he saw a strange beast come bounding over the grass toward them.', false, true),
  ('eng', 'long', 'Now it was his turn to beg her pardon; and she went into the day-nursery and played, and soon he was asleep; and while he slept, Wendy and John and Michael flew into the room.', false, true),
  ('eng', 'long', 'It was already getting towards dusk when he reached the first fringe of trees and plunged without hesitation into the wood, looking anxiously on either side for any sign of his friend.', false, true),
  ('eng', 'long', 'Elizabeth received her congratulations amongst the rest, and then, sick of this folly, took refuge in her own room, that she might think with freedom.', false, true),
  ('eng', 'long', 'She said my old one would do very well for another winter and that I ought to be satisfied with having a new dress. The dress is very pretty, Diana--navy blue and made so fashionably.', false, true),
  ('eng', 'long', 'She doesn’t know where home is! It’s England, of course. Our grandmama lives there and our sister Mabel was sent to her last year. You are not going to your grandmama.', false, true),
  ('eng', 'long', 'There was nothing else to do, so Alice soon began talking again. Dinah’ll miss me very much to-night, I should think! Dinah was the cat. I hope they’ll remember her saucer of milk at tea-time.', false, true),
  ('eng', 'long', 'They were early, and while Miss Crocker set the heel of her stocking, Jo amused herself by examining the faces of the people who occupied the seat with them.', false, true),
  ('eng', 'long', 'Instead of this there were these prosaic and troublesome directions, which were so unexpected that she took some time to get over her surprise and disappointment, and continued standing awaiting further explanation.', false, true),
  ('eng', 'long', 'There seemed to be no horses nor animals of any kind; the men carried things around in little green carts, which they pushed before them. Everyone seemed happy and contented and prosperous.', false, true),
  ('eng', 'long', 'They had caught her boarding the pirate ship with a knife in her mouth. No watch was kept on the ship, it being Hook’s boast that the wind of his name guarded the ship for a mile around.', false, true),
  ('eng', 'long', 'Then, as he looked, it winked at him, and so declared itself to be an eye; and a small face began gradually to grow up round it, like a frame round a picture.', false, true),
  ('eng', 'long', 'The park was very large, and contained great variety of ground. They entered it in one of its lowest points, and drove for some time through a beautiful wood stretching over a wide extent.', false, true),
  ('eng', 'long', 'Real self-sacrificing, too, for he’ll have his board to pay at White Sands, and everybody knows he’s got to earn his own way through college. So the trustees decided to take you.', false, true),
  ('eng', 'long', 'A boy, and a fox, and a crow, and two squirrels, and a new-born lamb, are coming to see me this morning. You are not to begin playing with the animals in the servants’ hall and keep them there.', false, true),
  ('eng', 'long', 'Alice waited a little, half expecting to see it again, but it did not appear, and after a minute or two she walked on in the direction in which the March Hare was said to live.', false, true),
  ('eng', 'long', 'It was not a happy evening, for though they sewed as usual, while their mother read aloud from Bremer, Scott, or Edgeworth, something was wanting, and the sweet home peace was disturbed.', false, true),
  ('eng', 'long', 'He had known her parents, and felt sure at once that this was the child of whom he had heard so much. He began to wonder why she had come back, and as they drove along he entered into conversation with her.', false, true),
  ('eng', 'long', 'Dorothy stood up and found she was in her stocking-feet. For the Silver Shoes had fallen off in her flight through the air, and were lost forever in the desert.', false, true),
  ('eng', 'long', 'It did not entirely fill the aperture, and he had been looking over it. Feeling for the catch, he found to his fury that it was low down, beyond his reach.', false, true),
  ('eng', 'long', 'However, talking won’t mend matters. He’s got clear away for the time, that’s certain; and the worst of it is, he’ll be so conceited with what he’ll think is his cleverness that he may commit any folly.', false, true),
  ('eng', 'long', 'And there are other circumstances which I am not at liberty--which it is not worth while to relate; but his lies about the whole Pemberley family are endless.', false, true),
  ('eng', 'long', 'Dear Stacy, it would be perfectly dreadful if you didn’t come back. I don’t believe I could have the heart to go on with my studies at all if another teacher came here.', false, true),
  ('eng', 'long', 'Mother says there’s no reason why any child should live that gets no fresh air an’ doesn’t do nothin’ but lie on his back an’ read picture-books an’ take medicine.', false, true),
  ('eng', 'long', 'It was so long since she had been anything near the right size, that it felt quite strange at first; but she got used to it in a few minutes, and began talking to herself, as usual.', false, true),
  ('eng', 'long', 'This cave was made with a clothes horse for a roof, bureaus for walls, and in it was a small furnace in full blast, with a black pot on it and an old witch bending over it.', false, true),
  ('eng', 'long', 'Epileptic fits and St. Vitus''s dance often came on suddenly in cases like this, and Clara was liable to be attacked by either if the cause of the general alarm was not removed.', false, true),
  ('eng', 'long', 'Dorothy came to meet them and thanked the little mice warmly for saving her companion from death. She had grown so fond of the big Lion she was glad he had been rescued.', false, true),
  ('eng', 'long', 'She was called Jane, and always had an odd inquiring look, as if from the moment she arrived on the mainland she wanted to ask questions. When she was old enough to ask them they were mostly about Peter Pan.', false, true),
  ('eng', 'long', 'The afternoon sun was getting low as the Rat sculled gently homewards in a dreamy mood, murmuring poetry-things over to himself, and not paying much attention to Mole.', false, true),
  ('eng', 'long', 'Elizabeth, as she affectionately embraced her, whilst tears filled the eyes of both, lost not a moment in asking whether anything had been heard of the fugitives.', false, true),
  ('eng', 'long', 'They went over to Orchard Slope by the short cut across the brook and up the firry hill grove. Mrs. Barry came to the kitchen door in answer to Marilla’s knock.', false, true),
  ('eng', 'long', 'Something he had heard Mrs. Medlock whispering to the nurse had given him the idea and he had thought over it in secret until it was quite firmly fixed in his mind.', false, true),
  ('eng', 'long', 'She went in without knocking, and hurried upstairs, in great fear lest she should meet the real Mary Ann, and be turned out of the house before she had found the fan and gloves.', false, true),
  ('eng', 'long', 'John Brooke laughed then as he never dared to laugh afterward, and the derisive Scott smiled involuntarily as he heard the hearty peal, which put the finishing stroke to poor Meg’s woe.', false, true),
  ('eng', 'long', 'Heidi quickly picked up her bundle, with a look of joy and gratitude. As she stood by the carriage door, Herr Sesemann gave her his hand and said he hoped she would remember him and Clara.', false, true),
  ('eng', 'long', 'Hour after hour passed away, and slowly Dorothy got over her fright; but she felt quite lonely, and the wind shrieked so loudly all about her that she nearly became deaf.', false, true),
  ('eng', 'long', 'Peter could not understand why, but Wendy understood, and she was just slightly disappointed when he admitted that he came to the nursery window not to see her but to listen to stories.', false, true),
  ('eng', 'long', 'The floor was well-worn red brick, and on the wide hearth burnt a fire of logs, between two attractive chimney-corners tucked away in the wall, well out of any suspicion of draught.', false, true),
  ('eng', 'long', 'I cannot forget the follies and vices of others so soon as I ought, nor their offences against myself. My feelings are not puffed about with every attempt to move them.', false, true),
  ('eng', 'long', 'Ruby Gillis says when she grows up she’s going to have ever so many beaus on the string and have them all crazy about her; but I think that would be too exciting.', false, true),
  ('eng', 'long', 'Ben Weatherstaff passed his hand over his forehead again and gazed as if he could never gaze enough. His hand shook and his mouth shook and his voice shook.', false, true),
  ('eng', 'long', 'After these came the royal children; there were ten of them, and the little dears came jumping merrily along hand in hand, in couples: they were all ornamented with hearts.', false, true),
  ('eng', 'long', 'Her eyes kindled as they turned wistfully toward the window, but they fell on the old house opposite, and she shook her head with sorrowful decision.', false, true),
  ('eng', 'long', 'The flowers had been too strong for the huge beast and he had given up at last, and fallen only a short distance from the end of the poppy bed, where the sweet grass spread in beautiful green fields before them.', false, true),
  ('eng', 'long', 'But not one dared to face the door. Yes, one, Wendy, who all this time had been bound to the mast. It was for neither a scream nor a crow that she was watching, it was for the reappearance of Peter.', false, true),
  ('eng', 'long', 'The Badger led them along by the river for a little way, and then suddenly swung himself over the edge into a hole in the river-bank, a little above the water.', false, true),
  ('eng', 'long', 'I was sure you could not be so beautiful for nothing! I remember, as soon as ever I saw him, when he first came into Hertfordshire last year, I thought how likely it was that you should come together.', false, true),
  ('eng', 'long', 'Everything is ready, Diana, except my cake which I’m to make in the morning, and the baking-powder biscuits which Marilla will make just before teatime.', false, true),
  ('eng', 'long', 'They were the sounds of running scuffling feet seeming to chase round and round under the trees, they were strange sounds of lowered suppressed voices—exclamations and smothered joyous cries.', false, true),
  ('eng', 'long', 'Presently the Rabbit came up to the door, and tried to open it; but, as the door opened inwards, and Alice’s elbow was pressed hard against it, that attempt proved a failure.', false, true),
  ('eng', 'long', 'Amy was drawing the lovers, who sat apart in a beautiful world of their own, the light of which touched their faces with a grace the little artist could not copy.', false, true),
  ('eng', 'long', 'Now we shall be able to come up here together every day, and go just where we like; and you will be able all your life to walk about as I do, and not have to be pushed in a chair, and you will get quite strong and well.', false, true),
  ('eng', 'long', 'While the Woodman was making a ladder from wood which he found in the forest Dorothy lay down and slept, for she was tired by the long walk. The Lion also curled himself up to sleep and Toto lay beside him.', false, true),
  ('eng', 'long', 'Mrs. Darling came to the window, for at present she was keeping a sharp eye on Wendy. She told Peter that she had adopted all the other boys, and would like to adopt him also.', false, true),
  ('eng', 'long', 'He stopped dead in his tracks, his nose searching hither and thither in its efforts to recapture the fine filament, the telegraphic current, that had so strongly moved him.', false, true),
  ('eng', 'long', 'A great deal of good management, depend upon it. Well, much good may it do them! And so, I suppose, they often talk of having Longbourn when your father is dead.', false, true),
  ('eng', 'long', 'I might have let her spend the night with Diana, if that was all. But I don’t approve of this concert plan. She’d go there and catch cold like as not, and have her head filled up with nonsense and excitement.', false, true),
  ('eng', 'long', 'There were tender little fluting sounds here and there and everywhere, as if scores of birds were beginning to tune up for a concert. Mary put her hand out of the window and held it in the sun.', false, true),
  ('eng', 'long', 'Poor Laurie didn’t know where to look, for, man though he was, something of the old bashfulness came over him as this burst of praise made all faces turn approvingly upon him.', false, true),
  ('eng', 'long', 'And Heidi nodded back to them, and grew every moment more wild with her joy and longing, feeling as if she must jump down from the cart and run with all her might till she reached the top.', false, true),
  ('eng', 'long', 'Then the Lion put his strong front legs against the tree and pushed with all his might, and slowly the big tree tipped and fell with a crash across the ditch, with its top branches on the other side.', false, true),
  ('eng', 'long', 'To induce her to look up he pretended to be going away, and when this failed he sat on the end of the bed and tapped her gently with his foot. I can’t help crowing, Wendy, when I’m pleased with myself.', false, true),
  ('eng', 'long', 'So once more they got on their feet, and struggled down into the dell, where they hunted about for a cave or some corner that was dry and a protection from the keen wind and the whirling snow.', false, true),
  ('eng', 'long', 'After walking several miles in a leisurely manner, and too busy to know anything about it, they found at last, on examining their watches, that it was time to be at home.', false, true),
  ('eng', 'long', 'Anne stood among them, bright eyed and animated as they; but Matthew suddenly became conscious that there was something about her different from her mates.', false, true),
  ('eng', 'long', 'That night Colin slept without once awakening and when he opened his eyes in the morning he lay still and smiled without knowing it—smiled because he felt so curiously comfortable.', false, true),
  ('eng', 'long', 'And yet what a dear little puppy it was! I’d nearly forgotten that I’ve got to grow up again! I suppose I ought to eat or drink something or other; but the great question is, what?', false, true),
  ('eng', 'long', 'I gave my best to the country I love, and kept my tears till he was gone. Why should I complain, when we both have merely done our duty and will surely be the happier for it in the end?', false, true),
  ('eng', 'long', 'Now, tell me, are Clara and you good friends with one another, or do you get angry and quarrel, and then cry and make it up, and then start quarreling again on the next occasion?', false, true),
  ('eng', 'long', 'But I spoke to him as he sat behind his screen and gave him your message. He said he will grant you an audience, if you so desire; but each one of you must enter his presence alone, and he will admit but one each day.', false, true),
  ('eng', 'long', 'Fain would his dogs have known, as breathing heavily and wiping their cutlasses, they gathered at a discreet distance from his hook, and squinted through their ferret eyes at this extraordinary man.', false, true),
  ('eng', 'long', 'On the walls hung wire baskets with ferns in them, alternating with brackets carrying plaster statuary—Garibaldi, and the infant Samuel, and Queen Victoria, and other heroes of modern Italy.', false, true),
  ('eng', 'long', 'My avowed one, or what I avowed to myself, was to see whether your sister was still partial to Bingley, and if she were, to make the confession to him which I have since made.', false, true),
  ('eng', 'long', 'I just feel tired of everything sensible and I’m going to let my imagination run riot for the summer. Oh, you needn’t be alarmed, Marilla. I’ll only let it run riot within reasonable limits.', false, true),
  ('eng', 'long', 'The scene which Dr. Craven beheld when he entered his patient’s room was indeed rather astonishing to him. As Mrs. Medlock opened the door he heard laughing and chattering.', false, true),
  ('eng', 'long', 'Next came the guests, mostly Kings and Queens, and among them Alice recognised the White Rabbit: it was talking in a hurried nervous manner, smiling at everything that was said, and went by without noticing her.', false, true),
  ('eng', 'long', 'Baron Rothschild’s private secretary, a large-nosed Jew in tight boots, affably beamed upon the world, as if his master’s name crowned him with a golden halo.', false, true),
  ('eng', 'long', 'Heidi wrapped it round something else which she laid on the top of the basket, so that the red package was quite conspicuous. Then she put on her pretty hat and left the room.', false, true),
  ('eng', 'long', 'But there is another way to make it float, which is to fill it with hot air. Hot air isn’t as good as gas, for if the air should get cold the balloon would come down in the desert, and we should be lost.', false, true),
  ('eng', 'long', 'Of course the Neverland had been make-believe in those days, but it was real now, and there were no night-lights, and it was getting darker every moment, and where was Nana?', false, true),
  ('eng', 'long', 'The Mole subsided forlornly on a tree-stump and tried to control himself, for he felt it surely coming. The sob he had fought with so long refused to be beaten.', false, true),
  ('eng', 'long', 'Elizabeth, feeling really anxious, determined to go to her, though the carriage was not to be had: and as she was no horsewoman, walking was her only alternative.', false, true),
  ('eng', 'long', 'Before Josie had told the news Anne’s highest pinnacle of aspiration had been a teacher’s provincial license, First Class, at the end of the year, and perhaps the medal!', false, true),
  ('eng', 'long', 'If I couldn’t keep secrets from th’ other lads, secrets about foxes’ cubs, an’ birds’ nests, an’ wild things’ holes, there’d be naught safe on th’ moor.', false, true),
  ('eng', 'long', 'As soon as she was small enough to get through the door, she ran out of the house, and found quite a crowd of little animals and birds waiting outside.', false, true),
  ('eng', 'long', 'Fifteen-year-old Jo was very tall, thin, and brown, and reminded one of a colt, for she never seemed to know what to do with her long limbs, which were very much in her way.', false, true),
  ('eng', 'long', 'Fraulein Rottenmeier was always very much annoyed that the old lady continually addressed her by her surname only; but it was no use minding, for the grandmother always went her own way, and so there was no help for it.', false, true),
  ('eng', 'long', 'Dorothy was going to ask another question, but just then the Munchkins, who had been standing silently by, gave a loud shout and pointed to the corner of the house where the Wicked Witch had been lying.', false, true),
  ('eng', 'long', 'Something of the strength of character of the man will be seen if we remember how sensitive he was to the opinion of neighbours: this man whose every movement now attracted surprised attention.', false, true),
  ('eng', 'long', 'It seemed, as the Mole remarked to the Rat, like some one walking in carpet slippers that were too large for him and down at heel; which was intelligent of Mole, because that was exactly what it was.', false, true),
  ('eng', 'long', 'The extravagance and general profligacy which he scrupled not to lay to Mr. Wickham’s charge exceedingly shocked her; the more so, as she could bring no proof of its injustice.', false, true),
  ('eng', 'long', 'Mrs. Lynde says ministers are dyspeptic, but I don’t think Mr. Allan has been a minister long enough for it to have had a bad effect on him. I just grow cold when I think of my layer cake.', false, true),
  ('eng', 'long', 'It just burst out because all at once I couldn’t help remembering that last big potato you ate and the way your mouth stretched when you bit through that thick lovely crust with jam and clotted cream on it.', false, true),
  ('eng', 'long', 'Alice looked at the jury-box, and saw that, in her haste, she had put the Lizard in head downwards, and the poor little thing was waving its tail about in a melancholy way, being quite unable to move.', false, true),
  ('eng', 'long', 'Why in the world should you spend your money, worry your family, and turn the house upside down for a parcel of girls who don’t care a sixpence for you?', false, true),
  ('eng', 'long', 'Peter got up on hearing her call, and together they sat and watched the bird, which rose higher and higher in the blue air till it disappeared behind the grey mountain-tops.', false, true),
  ('eng', 'long', 'So they kept walking until Dorothy could stand no longer. Her eyes closed in spite of herself and she forgot where she was and fell among the poppies, fast asleep.', false, true),
  ('eng', 'long', 'Now these three children had a faithful nurse called Nana; but Mr. Darling was angry with her and chained her up in the yard, and so all the children flew away.', false, true),
  ('eng', 'long', 'Then he disappeared into the caravan for an instant, and returned with a large iron plate and a knife, fork, and spoon. He tilted up the pot, and a glorious stream of hot rich stew gurgled into the plate.', false, true),
  ('eng', 'long', 'She grew absolutely ashamed of herself. Of neither Darcy nor Wickham could she think, without feeling that she had been blind, partial, prejudiced, absurd.', false, true),
  ('eng', 'long', 'The flood of tears would have come, no doubt, had not Josie Pye appeared at that moment. In the joy of seeing a familiar face Anne forgot that there had never been much love lost between her and Josie.', false, true),
  ('eng', 'long', 'Well, yes, I do. I was learned that by a young lady I was gardener to. She had a lot in a place she was fond of, an’ she loved ’em like they was children—or robins.', false, true),
  ('eng', 'long', 'This time Alice waited patiently until it chose to speak again. In a minute or two the Caterpillar took the hookah out of its mouth and yawned once or twice, and shook itself.', false, true),
  ('eng', 'long', 'It’s a greater not to be able to hide them. I don’t mind saying that I don’t approve of Tudor any more than you do, but I’m not called upon to tell him so.', false, true),
  ('eng', 'long', 'She was not allowed, however, a very long interval of time for consideration, for suddenly the sound of a frightful crash was heard in the study, followed by frantic cries for Sebastian.', false, true),
  ('eng', 'long', 'Of course this politeness was wasted on the Scarecrow; for when he found himself alone in his room he stood stupidly in one spot, just within the doorway, to wait till morning.', false, true),
  ('eng', 'long', 'On the contrary, he thought he had scaled her side as noiseless as a mouse; and he was amazed to see the pirates cowering from him, with Hook in their midst as abject as if he had heard the crocodile.', false, true),
  ('eng', 'long', 'The cuckoo, of course, had long been silent; but many another feathered friend, for months a part of the familiar landscape and its small society, was missing too and it seemed that the ranks thinned steadily day by day.', false, true),
  ('eng', 'long', 'Here again I shall give you pain--to what degree you only can tell. But whatever may be the sentiments which Mr. Wickham has created, a suspicion of their nature shall not prevent me from unfolding his real character.', false, true),
  ('eng', 'long', 'All the school girls and boys had one golden afternoon gathering them, coming home in the clear, echoing twilight with arms and baskets full of flowery spoil.', false, true),
  ('eng', 'long', 'But then she said indulgently that humans were always more clumsy and slow than Eggs and most of them never seemed really to learn to fly at all. You never met them in the air or on tree-tops.', false, true),
  ('eng', 'long', 'Alice noticed with some surprise that the pebbles were all turning into little cakes as they lay on the floor, and a bright idea came into her head.', false, true),
  ('eng', 'long', 'So the toast was drunk, the pledge made and loyally kept in spite of many temptations, for with instinctive wisdom, the girls seized a happy moment to do their friend a service, for which he thanked them all his life.', false, true),
  ('eng', 'long', 'Finally there was a whole lot of mysterious little bags, and parcels, and boxes, which Clara had had especial pleasure in collecting, as each was to be a joyful surprise for Heidi as she opened it.', false, true),
  ('eng', 'long', 'There were forty crows, and forty times the Scarecrow twisted a neck, until at last all were lying dead beside him. Then he called to his companions to rise, and again they went upon their journey.', false, true),
  ('eng', 'long', 'Great were the rejoicings when Peter reached the home under the ground almost as soon as Wendy, who had been carried hither and thither by the kite.', false, true),
  ('eng', 'long', 'He struck out for the shore, but the cotton gown greatly impeded his efforts, and when at length he touched land he found it hard to climb up the steep bank unassisted.', false, true),
  ('eng', 'long', 'My father supported him at school, and afterwards at Cambridge; most important assistance, as his own father, always poor from the extravagance of his wife, would have been unable to give him a gentleman’s education.', false, true),
  ('eng', 'long', 'She told Matthew the story the next morning. Matthew was confounded and puzzled; he could not so quickly lose faith in Anne but he had to admit that circumstances were against her.', false, true),
  ('eng', 'long', 'She thought she remembered the corners she must turn to find the short corridor with the door covered with tapestry—the one Mrs. Medlock had come through the day she lost herself.', false, true),
  ('eng', 'long', 'And so she went on, taking first one side and then the other, and making quite a conversation of it altogether; but after a few minutes she heard a voice outside, and stopped to listen.', false, true),
  ('eng', 'long', 'It was the best thing he could have done, far more soothing than the most eloquent words, for Jo felt the unspoken sympathy, and in the silence learned the sweet solace which affection administers to sorrow.', false, true),
  ('eng', 'long', 'A table was close to the door, and as Heidi stepped in she saw a woman sitting at it, putting a patch on a waistcoat which Heidi recognised at once as Peter''s.', false, true),
  ('eng', 'long', 'Dorothy was shocked to see that the cow had broken her leg off, and that the pail was lying in several small pieces, while the poor milkmaid had a nick in her left elbow.', false, true),
  ('eng', 'long', 'All the boys were plucked from their trees in this ruthless manner; and several of them were in the air at a time, like bales of goods flung from hand to hand.', false, true),
  ('eng', 'long', 'The past was like a bad dream; the future was all happy holiday as I moved southwards week by week, easily, lazily, lingering as long as I dared, but always heeding the call!', false, true),
  ('eng', 'long', 'Our distress, my dear Lizzy, is very great. My father and mother believe the worst, but I cannot think so ill of him. I grieve to find, however, that Colonel F.', false, true),
  ('eng', 'long', 'And then, her temper’s pretty quick, I guess; but there’s one comfort, a child that has a quick temper, just blaze up and cool down, ain’t never likely to be sly or deceitful.', false, true),
  ('eng', 'long', 'I know what tha’s up to. Tha’s courtin’ some bold young madam somewhere tellin’ thy lies to her about bein’ th’ finest cock robin on Missel Moor an’ ready to fight all th’ rest of ’em.', false, true),
  ('eng', 'long', 'The Duchess took no notice of them even when they hit her; and the baby was howling so much already, that it was quite impossible to say whether the blows hurt it or not.', false, true),
  ('eng', 'long', 'Meg had a cushion, Jo a book, Beth a basket, and Amy a portfolio. All walked quietly through the garden, out at the little back gate, and began to climb the hill that lay between the house and river.', false, true),
  ('eng', 'long', 'The angry looks which Peter had from the beginning cast at Clara, and the other signs of his dislike to what had been taking place on the mountain, had not escaped Uncle''s eye.', false, true),
  ('eng', 'long', 'She crept to the hole, caught Toto by the ear, and dragged him into the room again, afterward closing the trap door so that no more accidents could happen.', false, true),
  ('eng', 'long', 'Now Smee had found the tom-tom, and was at that moment sitting on it. To his amazement Hook signed him to beat the tom-tom, and slowly there came to Smee an understanding of the dreadful wickedness of the order.', false, true),
  ('eng', 'long', 'Still, Toad was not inclined to give in all at once. So he got out the boat, and set off rowing up the river to where the garden front of Toad Hall came down to the waterside.', false, true),
  ('eng', 'long', 'My dear Lizzy, where can you have been walking to? She had only to say in reply, that they had wandered about till she was beyond her own knowledge.', false, true),
  ('eng', 'long', 'Then, just as she thought she really could not endure the ache in her arms and wrists another moment, Gilbert Blythe came rowing under the bridge in Harmon Andrews’s dory!', false, true),
  ('eng', 'long', 'He hopped about and pecked the earth briskly, looking for seeds and insects. It actually gave Mary a queer feeling in her heart, because he was so pretty and cheerful and seemed so like a person.', false, true),
  ('eng', 'long', 'She was a good deal frightened by this very sudden change, but she felt that there was no time to be lost, as she was shrinking rapidly; so she set to work at once to eat some of the other bit.', false, true),
  ('eng', 'long', 'They talked over the new plan while old Hannah cleared the table, then out came the four little work baskets, and the needles flew as the girls made sheets for Aunt March.', false, true),
