  ('eng', 'long', 'The eyes winked three times, and then they turned up to the ceiling and down to the floor and rolled around so queerly that they seemed to see every part of the room.', false, true),
  ('eng', 'long', 'But you simply must fit, and Peter measures you for your tree as carefully as for a suit of clothes: the only difference being that the clothes are made to fit you, while you have to be made to fit the tree.', false, true),
  ('eng', 'long', 'But it was good to think he had this to come back to; this place which was all his own, these things which were so glad to see him again and could always be counted upon for the same simple welcome.', false, true),
  ('eng', 'long', 'Everything was too recent for gaiety, but the evening passed tranquilly away; there was no longer anything material to be dreaded, and the comfort of ease and familiarity would come in time.', false, true),
  ('eng', 'long', 'Anne thought those Friday evening gypsyings over the autumnal hills in the crisp golden air, with the homelights of Avonlea twinkling beyond, were the best and dearest hours in the whole week.', false, true),
  ('eng', 'long', 'At first Mary thought that there were no lights at all in the windows, but as she got out of the carriage she saw that one room in a corner upstairs showed a dull glow.', false, true),
  ('eng', 'long', 'Here one of the guinea-pigs cheered, and was immediately suppressed by the officers of the court. As that is rather a hard word, I will just explain to you how it was done.', false, true),
  ('eng', 'long', 'I should like to ask the girls out to lunch next week, to take them for a drive to the places they want to see, a row on the river, perhaps, and make a little artistic fete for them.', false, true),
  ('eng', 'long', 'How grandfather had made Clara try first to stand and then to move her feet a little every day, and how they had settled for the day''s excursion up the mountain and the chair had been blown away.', false, true),
