  ('eng', 'long', 'Then he burst into tears, and the truth came out. He was as glad to have them as she was, he said, but he thought they should have asked his consent as well as hers, instead of treating him as a cypher in his own house.', false, true),
  ('eng', 'long', 'In the osiers which fringed the bank he spied a swallow sitting. Presently it was joined by another, and then by a third; and the birds, fidgeting restlessly on their bough, talked together earnestly and low.', false, true),
  ('eng', 'long', 'She felt anew the justice of Mr. Darcy’s objections; and never had she before been so much disposed to pardon his interference in the views of his friend.', false, true),
  ('eng', 'long', 'In a trice Anne was out of the house and flying down to the hollow, astonishment and hope struggling in her expressive eyes. But the hope faded when she saw Diana’s dejected countenance.', false, true),
  ('eng', 'long', 'She walked away, slowly thinking. She had begun to like the garden just as she had begun to like the robin and Dickon and Martha’s mother. She was beginning to like Martha, too.', false, true),
  ('eng', 'long', 'The unfortunate little Bill had left off writing on his slate with one finger, as he found it made no mark; but he now hastily began again, using the ink, that was trickling down his face, as long as it lasted.', false, true),
  ('eng', 'long', 'She only saw his chest rise and fall, with a long breath that might have been a sigh, and the hand that wore the ring nestled down into the grass, as if to hide something too precious or too tender to be spoken of.', false, true),
  ('eng', 'long', 'On the morning of this day she had come all the way from Ragatz with the child, a friend having given them a lift in a hay-cart as far as Mayenfeld.', false, true),
  ('eng', 'long', 'But at noon, when the sun was over their heads, they did not know which was east and which was west, and that was the reason they were lost in the great fields.', false, true),
  ('eng', 'long', 'What I mean is, the Banquet will be at night, of course, but the invitations will have to be written and got off at once, and you’ve got to write ’em.', false, true),
  ('eng', 'long', 'Mrs. Bennet was, in fact, too much overpowered to say a great deal while Sir William remained; but no sooner had he left them than her feelings found a rapid vent.', false, true),
  ('eng', 'long', 'Now, Anne, I noticed last night that you threw your clothes all about the floor when you took them off. That is a very untidy habit, and I can’t allow it at all.', false, true),
  ('eng', 'long', 'Could you keep a secret, if I told you one? It’s a great secret. I don’t know what I should do if anyone found it out. I believe I should die! She said the last sentence quite fiercely.', false, true),
  ('eng', 'long', 'Just then her head struck against the roof of the hall: in fact she was now more than nine feet high, and she at once took up the little golden key and hurried off to the garden door.', false, true),
  ('eng', 'long', 'Why, I owe at least a dozen pickled limes, and I can’t pay them, you know, till I have money, for Marmee forbade my having anything charged at the shop.', false, true),
  ('eng', 'long', 'Uncle stood near, looking now at the fresh faces of the children, now at his well-kept goats, with a smile on his face, evidently well pleased with the sight of both.', false, true),
  ('eng', 'long', 'One of my greatest fears was the Witches, for while I had no magical powers at all I soon found out that the Witches were really able to do wonderful things.', false, true),
  ('eng', 'long', 'John said that if the worst came to the worst, all they had to do was to go straight on, for the world was round, and so in time they must come back to their own window.', false, true),
  ('eng', 'long', 'The whole family in short were properly overjoyed on the occasion. Charlotte herself was tolerably composed. She had gained her point, and had time to consider of it.', false, true),
  ('eng', 'long', 'Anne looked earnestly into her friend’s face. I think you won’t misunderstand me when I say I want to be alone. I’m not afraid. I haven’t been alone one minute since it happened--and I want to be.', false, true),
  ('eng', 'long', 'How can we know the exact names of everything? Sing it again, Dickon. Let us try, Mary. I want to sing it, too. It’s my song. How does it begin? Praise God from whom all blessings flow’?', false, true),
  ('eng', 'long', 'This speech caused a remarkable sensation among the party. It’s high time you were all in bed! On various pretexts they all moved off, and Alice was soon left alone.', false, true),
  ('eng', 'long', 'As the omnibus contained only one other passenger, a sleepy old lady, Amy pocketed her veil and beguiled the tedium of the way by trying to find out where all her money had gone to.', false, true),
  ('eng', 'long', 'Heidi ran in, and taking her little stool immediately sat down by grandmother and began eagerly pouring out all her news, growing more excited with her pleasure as she went on.', false, true),
  ('eng', 'long', 'This gave the Lion a hint of the best way to attack the creature, and as he knew it was easier to fight it asleep than awake, he gave a great spring and landed directly upon the monster’s back.', false, true),
  ('eng', 'long', 'Of course she should have roused the children at once; not merely because of the unknown that was stalking toward them, but because it was no longer good for them to sleep on a rock grown chilly.', false, true),
  ('eng', 'long', 'A long half-hour passed, and every minute of it saw Toad getting crosser and crosser. Nothing that he could do to the things seemed to please them or do them good.', false, true),
  ('eng', 'long', 'When she came to that part of the letter in which her family were mentioned, in tones of such mortifying, yet merited, reproach, her sense of shame was severe.', false, true),
  ('eng', 'long', 'I looked carefully at all the dark men I saw after that, but I didn’t care much for any of them, and anyhow I suppose it’s too early to be looking out for him yet.', false, true),
  ('eng', 'long', 'Ben Weatherstaff’s crabbed old face was still wet with that one queer rush of tears. It seemed as if he could not take his eyes from thin straight Colin standing on his feet with his head thrown back.', false, true),
  ('eng', 'long', 'If I shouldn’t be in the way, it would be very pleasant. I begin to feel quite young already, for somehow all my troubles seemed to fly away when you came.', false, true),
  ('eng', 'long', 'Clara had now been on the mountain for three weeks. And Clara had made the effort in order to please him, but had clung to him as soon as her feet touched the ground, exclaiming that it hurt her so.', false, true),
  ('eng', 'long', 'And, strangest of all, these people were all made of china, even to their clothes, and were so small that the tallest of them was no higher than Dorothy’s knee.', false, true),
  ('eng', 'long', 'When playing Follow my Leader, Peter would fly close to the water and touch each shark’s tail in passing, just as in the street you may run your finger along an iron railing.', false, true),
  ('eng', 'long', 'This canal joins the river some miles further on, a little above Toad Hall; and then it’s an easy walk. You come along in the barge with me, and I’ll give you a lift.', false, true),
  ('eng', 'long', 'You and the girls may go--or you may send them by themselves, which perhaps will be still better; for as you are as handsome as any of them, Mr. Bingley might like you the best of the party.', false, true),
