  ('eng', 'long', 'No one would dare to follow us. There are galleries where you could run. We could do our exercises. There is a little Indian room where there is a cabinet full of ivory elephants.', false, true),
  ('eng', 'long', 'And so it was indeed: she was now only ten inches high, and her face brightened up at the thought that she was now the right size for going through the little door into that lovely garden.', false, true),
  ('eng', 'long', 'You said the other day you thought we were a deal happier than the King children, for they were fighting and fretting all the time, in spite of their money.', false, true),
  ('eng', 'long', 'And it was difficult to say which of the three looked the happiest at being together again, and at the recollection of all the wonderful things that had happened.', false, true),
  ('eng', 'long', 'The tree made a good, thick covering to protect them from the dew, and the Tin Woodman chopped a great pile of wood with his axe and Dorothy built a splendid fire that warmed her and made her feel less lonely.', false, true),
