  ('eng', 'long', 'Fair fresh leaves, and buds—and buds—tiny at first but swelling and working Magic until they burst and uncurled into cups of scent delicately spilling themselves over their brims and filling the garden air.', false, true),
  ('eng', 'long', 'Oh, my poor little feet, I wonder who will put on your shoes and stockings for you now, dears? Let me see: I’ll give them a new pair of boots every Christmas.', false, true),
  ('eng', 'long', 'If all brothers were treated as well as Laurie was at this period, they would be a much happier race of beings than they are. Amy never lectured now.', false, true),
  ('eng', 'long', 'Heidi had not dared to ask Fraulein Rottenmeier again how she was to address the grandmother: she thought the lady had perhaps made a mistake, for she had never heard any one called by other than their right name.', false, true),
  ('eng', 'long', 'Uncle Henry never laughed. He worked hard from morning till night and did not know what joy was. He was gray also, from his long beard to his rough boots, and he looked stern and solemn, and rarely spoke.', false, true),
  ('eng', 'long', 'Then for long he remained brooding; his hat of ill omen on the sward, so that any gentle breeze which had arisen might play refreshingly through his hair.', false, true),
  ('eng', 'long', 'One fine morning the Rat, whose turn it was to go on duty, went upstairs to relieve Badger, whom he found fidgeting to be off and stretch his legs in a long ramble round his wood and down his earths and burrows.', false, true),
  ('eng', 'long', 'You mistake me, my dear. I have a high respect for your nerves. They are my old friends. I have heard you mention them with consideration these twenty years at least.', false, true),
  ('eng', 'long', 'Reluctant admiration greeted her exploit, for most of the other girls could appreciate it, having suffered many things themselves in their efforts to walk fences.', false, true),
  ('eng', 'long', 'What in heaven’s name was he dreaming of—what in heaven’s name did he hear? Was he losing his reason and thinking he heard things which were not for human ears?', false, true),
  ('eng', 'long', 'I wonder how many miles I’ve fallen by this time? I must be getting somewhere near the centre of the earth. Alice had no idea what Latitude was, or Longitude either, but thought they were nice grand words to say.', false, true),
  ('eng', 'long', 'You are not a dandy, thank Heaven, so I’m glad to see there are no diamonds or big seal rings on it, only the little old one Jo gave you so long ago.', false, true),
