  ('eng', 'long', 'So he walked forward to the tree, but just as he came under the first branches they bent down and twined around him, and the next minute he was raised from the ground and flung headlong among his fellow travelers.', false, true),
  ('eng', 'long', 'The children often spent long summer days on this lagoon, swimming or floating most of the time, playing the mermaid games in the water, and so forth.', false, true),
  ('eng', 'long', 'The Mole waggled his toes from sheer happiness, spread his chest with a sigh of full contentment, and leaned back blissfully into the soft cushions.', false, true),
  ('eng', 'long', 'Elizabeth now expected that she would produce a letter for her from Charlotte, as it seemed the only probable motive for her calling. But no letter appeared, and she was completely puzzled.', false, true),
  ('eng', 'long', 'Oh, Mrs. Barry, please forgive me. I did not mean to--to--intoxicate Diana. Just imagine if you were a poor little orphan girl that kind people had adopted and you had just one bosom friend in all the world.', false, true),
  ('eng', 'long', 'One place she went to oftener than to any other. It was the long walk outside the gardens with the walls round them. There were bare flower-beds on either side of it and against the walls ivy grew thickly.', false, true),
  ('eng', 'long', 'William the Conqueror, whose cause was favoured by the pope, was soon submitted to by the English, who wanted leaders, and had been of late much accustomed to usurpation and conquest.', false, true),
  ('eng', 'long', 'The boiled tea was very bitter, the omelet scorched, and the biscuits speckled with saleratus, but Mrs. March received her repast with thanks and laughed heartily over it after Jo was gone.', false, true),
  ('eng', 'long', 'You have brought up all kinds of shawls and covers with you, and we could make up a soft bed out of them, and as to the general looking after the child, you need have no fear, for I will see to that.', false, true),
  ('eng', 'long', 'The Lion became quite angry at the laughter caused by the Scarecrow’s mishap, and giving a loud roar that echoed like thunder, he dashed up the hill.', false, true),
  ('eng', 'long', 'Also he was fond of variety, and the sport that engrossed him one moment would suddenly cease to engage him, so there was always the possibility that the next time you fell he would let you go.', false, true),
  ('eng', 'long', 'Here they saw many handsome boats, slung from the cross beams or hauled up on a slip, but none in the water; and the place had an unused and a deserted air.', false, true),
  ('eng', 'long', 'Elizabeth could safely say that it was a great happiness where that was the case, and with equal sincerity could add, that she firmly believed and rejoiced in his domestic comforts.', false, true),
  ('eng', 'long', 'You’ve grown up now and you’re going away; and you look so tall and stylish and so--so--different altogether in that dress--as if you didn’t belong in Avonlea at all--and I just got lonesome thinking it all over.', false, true),
  ('eng', 'long', 'I got up and looked out of the window. The room was quite light and there was a patch of moonlight on the curtain and somehow that made me go and pull the cord.', false, true),
  ('eng', 'long', 'Everything is so out-of-the-way down here, that I should think very likely it can talk: at any rate, there’s no harm in trying. I am very tired of swimming about here, O Mouse!', false, true),
  ('eng', 'long', 'Then the Professor thanked him so heartily, and looked so suddenly illuminated with satisfaction, that Laurie thought him the most delightfully demonstrative old fellow he ever met.', false, true),
  ('eng', 'long', 'It was easy to see that Snowflake enjoyed this peaceful and sheltered way of feeding, for when with the other goats she had much persecution to endure from the larger and stronger ones of the flock.', false, true),
  ('eng', 'long', 'Once more they could see fences built beside the road; but these were painted green, and when they came to a small house, in which a farmer evidently lived, that also was painted green.', false, true),
  ('eng', 'long', 'Unfortunately Liza returned to her puddings, and Nana, seeing that no help would come from her, strained and strained at the chain until at last she broke it.', false, true),
  ('eng', 'long', 'They could see the gape of his tiny beak as he yawned in a bored sort of way, looked round, and then settled his head into his back again, while the ruffled feathers gradually subsided into perfect stillness.', false, true),
  ('eng', 'long', 'But against this there were objections; and she finally resolved that it could be the last resource, if her private inquiries as to the absence of the family were unfavourably answered.', false, true),
  ('eng', 'long', 'Anne, you sit here on the ottoman and don’t wriggle. Let me take your hats. Flora Jane, go out and put the kettle on. Good afternoon, Mrs. Blewett. We were just saying how fortunate it was you happened along.', false, true),
  ('eng', 'long', 'One morning when the rain streamed down unceasingly and Colin was beginning to feel a little restive, as he was obliged to remain on his sofa because it was not safe to get up and walk about, Mary had an inspiration.', false, true),
  ('eng', 'long', 'Alice did not quite know what to say to this: so she helped herself to some tea and bread-and-butter, and then turned to the Dormouse, and repeated her question.', false, true),
  ('eng', 'long', 'Feeling this, Jo’s burden seemed easier to bear, duty grew sweeter, and life looked more endurable, seen from the safe shelter of her mother’s arms.', false, true),
  ('eng', 'long', 'But I should like you to have something for a pleasant reminder of the visitors from Frankfurt. Can you tell me anything that you have wished very much to have?', false, true),
  ('eng', 'long', 'When the Tin Woodman walked about he felt his heart rattling around in his breast; and he told Dorothy he had discovered it to be a kinder and more tender heart than the one he had owned when he was made of flesh.', false, true),
  ('eng', 'long', 'But Wendy had not been dreaming, as the very next night showed, the night on which the extraordinary adventures of these children may be said to have begun.', false, true),
  ('eng', 'long', 'For this is the last best gift that the kindly demi-god is careful to bestow on those to whom he has revealed himself in their helping: the gift of forgetfulness.', false, true),
  ('eng', 'long', 'To Kitty, however, it does not seem so wholly unexpected. I am very, very sorry. So imprudent a match on both sides! But I am willing to hope the best, and that his character has been misunderstood.', false, true),
  ('eng', 'long', 'That’s the White Sands Hotel. Mr. Kirke runs it, but the season hasn’t begun yet. There are heaps of Americans come there for the summer. They think this shore is just about right.', false, true),
  ('eng', 'long', 'Presently an old man with a spade over his shoulder walked through the door leading from the second garden. He looked startled when he saw Mary, and then touched his cap.', false, true),
  ('eng', 'long', 'I shall never get to twenty at that rate! However, the Multiplication Table doesn’t signify: let’s try Geography. I must have been changed for Mabel!', false, true),
  ('eng', 'long', 'Sitting on the floor with one boot on, Amy began to cry and Meg to reason with her, when Laurie called from below, and the two girls hurried down, leaving their sister wailing.', false, true),
  ('eng', 'long', 'Even then she could not see what she longed for. In vain she went first to one and then the other of the windows--she could see nothing but walls and windows and again walls and windows.', false, true),
  ('eng', 'long', 'She sat down on the grass and looked at her companions, and they sat down and looked at her, and Toto found that for the first time in his life he was too tired to chase a butterfly that flew past his head.', false, true),
  ('eng', 'long', 'Of course no one really knows, but he quite seemed to know, and he often said stocks were up and shares were down in a way that would have made any woman respect him.', false, true),
  ('eng', 'long', 'Everybody hereabouts knows him and likes him, just as they do old Otter, and you may be sure some animal or other will come across him and bring him back again all right.', false, true),
  ('eng', 'long', 'With such kind of histories of their parties and good jokes did Lydia, assisted by Kitty’s hints and additions, endeavour to amuse her companions all the way to Longbourn.', false, true),
  ('eng', 'long', 'WITH the end of June came the close of the term and the close of Miss Stacy’s rule in Avonlea school. Anne and Diana walked home that evening feeling very sober indeed.', false, true),
  ('eng', 'long', 'An’ he flies out at John, th’ footman, for not carryin’ him careful enough. He makes himself as helpless lookin’ as he can an’ never lifts his head until we’re out o’ sight o’ th’ house.', false, true),
  ('eng', 'long', 'Alice had no idea what to do, and in despair she put her hand in her pocket, and pulled out a box of comfits, (luckily the salt water had not got into it), and handed them round as prizes.', false, true),
  ('eng', 'long', 'Amy never would pet him like the others, but she was very glad to see him now, and quite clung to him, feeling that he was the representative of the dear family for whom she longed more than she would confess.', false, true),
  ('eng', 'long', 'Sebastian disappeared on the spot. Never let me hear you speak to him in that way again! It is the same with Tinette, and for myself you are to address me as you hear others doing.', false, true),
  ('eng', 'long', 'The Cowardly Lion was much pleased to hear that the Wicked Witch had been melted by a bucket of water, and Dorothy at once unlocked the gate of his prison and set him free.', false, true),
  ('eng', 'long', 'He peeped in again to see why the music had stopped, and now he saw that Mrs. Darling had laid her head on the box, and that two tears were sitting on her eyes.', false, true),
  ('eng', 'long', 'The Mole’s ran a good deal on supper, as it was pitch-dark, and it was all a strange country for him as far as he knew, and he was following obediently in the wake of the Rat, leaving the guidance entirely to him.', false, true),
  ('eng', 'long', 'My poor mother is really ill, and keeps her room. Could she exert herself, it would be better, but this is not to be expected; and as to my father, I never in my life saw him so affected.', false, true),
  ('eng', 'long', 'It isn’t delicate when I’ve got so many. But I do think that writing take-notices up on the wall about the boys and girls is the silliest ever. I should just like to see anybody dare to write my name up with a boy’s.', false, true),
  ('eng', 'long', 'The man held a salver with some letters on it and he waited quietly until Mr. Craven took them. When he had gone away Mr. Craven sat a few moments holding them in his hand and looking at the lake.', false, true),
  ('eng', 'long', 'Alice was not a bit hurt, and she jumped up on to her feet in a moment: she looked up, but it was all dark overhead; before her was another long passage, and the White Rabbit was still in sight, hurrying down it.', false, true),
  ('eng', 'long', 'She missed her mother’s help to understand and rule herself, but having been taught where to look, she did her best to find the way and walk in it confidingly.', false, true),
  ('eng', 'long', 'She entered into the lives of all the people she read about so that they became like dear friends to her, and it delighted her more and more to be with them.', false, true),
  ('eng', 'long', 'Sometimes she would cry bitterly for hours, with Toto sitting at her feet and looking into her face, whining dismally to show how sorry he was for his little mistress.', false, true),
  ('eng', 'long', 'To describe them all would require a book as large as an English-Latin, Latin-English Dictionary, and the most we can do is to give one as a specimen of an average hour on the island.', false, true),
  ('eng', 'long', 'As they neared the door it was flung open, and Mr. Toad, arrayed in goggles, cap, gaiters, and enormous overcoat, came swaggering down the steps, drawing on his gauntleted gloves.', false, true),
  ('eng', 'long', 'Its windows, opening to the ground, admitted a most refreshing view of the high woody hills behind the house, and of the beautiful oaks and Spanish chestnuts which were scattered over the intermediate lawn.', false, true),
  ('eng', 'long', 'Anne was dressing for a concert at the White Sands Hotel. The guests had got it up in aid of the Charlottetown hospital, and had hunted out all the available amateur talent in the surrounding districts to help it along.', false, true),
  ('eng', 'long', 'One of the new things people began to find out in the last century was that thoughts—just mere thoughts—are as powerful as electric batteries—as good for one as sunlight is, or as bad for one as poison.', false, true),
  ('eng', 'long', 'The twelve jurors were all writing very busily on slates. What are they doing? Alice whispered to the Gryphon. They can’t have anything to put down yet, before the trial’s begun.', false, true),
  ('eng', 'long', 'The pleasantest room in the house was set apart for Beth, and in it was gathered everything that she most loved, flowers, pictures, her piano, the little worktable, and the beloved pussies.', false, true),
  ('eng', 'long', 'He allowed Heidi to do what she liked with him, for he was reduced to such a state of low spirits and meekness that he was ready to give his help to Clara without murmur or resistance.', false, true),
  ('eng', 'long', 'But we were careless and happy and full of fun, and enjoyed every minute of the day. This was many years ago, long before Oz came out of the clouds to rule over this land.', false, true),
  ('eng', 'long', 'His eyes were of the blue of the forget-me-not, and of a profound melancholy, save when he was plunging his hook into you, at which time two red spots appeared in them and lit them up horribly.', false, true),
  ('eng', 'long', 'Better go ahead and dance your jig round that if you’ve got to, and get it over, and then perhaps we can go on and not waste any more time over rubbish-heaps.', false, true),
  ('eng', 'long', 'So much the better. It will save me a world of trouble and economy. I shall offer to pay him to-morrow, he will rant and storm about his love for you, and there will be an end of the matter.', false, true),
  ('eng', 'long', 'I couldn’t eat anything. My heart is broken. You’ll feel remorse of conscience someday, I expect, for breaking it, Marilla, but I forgive you. Remember when the time comes that I forgive you.', false, true),
  ('eng', 'long', 'That’s how he made friends with th’ pony. He’s got sheep on th’ moor that knows him, an’ birds as comes an’ eats out of his hand. However little there is to eat, he always saves a bit o’ his bread to coax his pets.', false, true),
  ('eng', 'long', 'Presently she began again. How funny it’ll seem to come out among the people that walk with their heads downward! Please, Ma’am, is this New Zealand or Australia?', false, true),
  ('eng', 'long', 'I want to do something splendid before I go into my castle, something heroic or wonderful that won’t be forgotten after I’m dead. I don’t know what, but I’m on the watch for it, and mean to astonish you all some day.', false, true),
  ('eng', 'long', 'But now I have something else to say. Independent of her circumstances, the child is totally unfitted to live a life away from home; we found out that when she was with us.', false, true),
  ('eng', 'long', 'On the feet were some old boots with blue tops, such as every man wore in this country, and the figure was raised above the stalks of corn by means of the pole stuck up its back.', false, true),
  ('eng', 'long', 'There was no other course but to press forward in redskin fashion, at which happily he was an adept. But in what direction, for he could not be sure that the children had been taken to the ship?', false, true),
  ('eng', 'long', 'Near him stood a dingy gipsy caravan, and beside it a man was sitting on a bucket turned upside down, very busy smoking and staring into the wide world.', false, true),
  ('eng', 'long', 'And will you give yourself the trouble of carrying similar assurances to his creditors in Meryton, of whom I shall subjoin a list, according to his information?', false, true),
  ('eng', 'long', 'I never really supposed I would, but so many of my loveliest dreams have come true all at once that perhaps this one will, too. Do you think it’s possible?', false, true),
  ('eng', 'long', 'The carriage lamps shed a yellow light on a rough-looking road which seemed to be cut through bushes and low-growing things which ended in the great expanse of dark apparently spread out before and around them.', false, true),
  ('eng', 'long', 'This did not seem to encourage the witness at all: he kept shifting from one foot to the other, looking uneasily at the Queen, and in his confusion he bit a large piece out of his teacup instead of the bread-and-butter.', false, true),
  ('eng', 'long', 'I’m not so silly and weak as you think. I know just what I should say, for I’ve planned it all, so I needn’t be taken unawares. There’s no knowing what may happen, and I wished to be prepared.', false, true),
  ('eng', 'long', 'And she rose and fled into the study and locked the door, so as to make sure that she was safe from the kittens, which to her were the most horrible things in creation.', false, true),
  ('eng', 'long', 'One thing I should like to do immensely, and that is to tell her, in the way authors have, that the children are coming back, that indeed they will be here on Thursday week.', false, true),
  ('eng', 'long', 'The Mole fell backwards on the snow from sheer surprise and delight. A real wonder, that’s what you are. I see it all now! And then you turned to and found the very door-scraper that done it!', false, true),
  ('eng', 'long', 'My father was not only fond of this young man’s society, whose manners were always engaging, he had also the highest opinion of him, and hoping the church would be his profession, intended to provide for him in it.', false, true),
  ('eng', 'long', 'The woods were all gloried through with sunset and the warm splendor of it streamed down through the hill gaps in the west. Matthew walked slowly with bent head; Anne, tall and erect, suited her springing step to his.', false, true),
  ('eng', 'long', 'She had a little thin face and a little thin body, thin light hair and a sour expression. Her hair was yellow, and her face was yellow because she had been born in India and had always been ill in one way or another.', false, true),
  ('eng', 'long', 'It was opened by another footman in livery, with a round face, and large eyes like a frog; and both footmen, Alice noticed, had powdered hair that curled all over their heads.', false, true),
  ('eng', 'long', 'Gladly would I give it if I could, but I only know that it was the whim of my timid Viola, and I yielded to it. Now, my children, let the play end. Unmask and receive my blessing.', false, true),
  ('eng', 'long', 'Above them waved whole bushes of the deep blue bell-flowers; while the fragrance that arose from the whole sunlit expanse was as if the rarest balsam had been flung over it.', false, true),
  ('eng', 'long', 'Then they lifted him up and flew away with him to the Witch’s castle, where he was placed in a small yard with a high iron fence around it, so that he could not escape.', false, true),
  ('eng', 'long', 'What sort of form was Hook himself showing? Misguided man though he was, we may be glad, without sympathising with him, that in the end he was true to the traditions of his race.', false, true),
  ('eng', 'long', 'To-day, to him gazing South with a new-born need stirring in his heart, the clear sky over their long low outline seemed to pulsate with promise; to-day, the unseen was everything, the unknown the only real fact of life.', false, true),
  ('eng', 'long', 'I think it is no sacrifice to join occasionally in evening engagements. Society has claims on us all; and I profess myself one of those who consider intervals of recreation and amusement as desirable for everybody.', false, true),
  ('eng', 'long', 'Her husband was a British officer, and she is very careful what sort of boarders she takes. Anne will not meet with any objectionable persons under her roof.', false, true),
  ('eng', 'long', 'He turned his head on his pillow and shut his eyes and a big tear was squeezed out and ran down his cheek. He was beginning to feel pathetic and sorry for himself—not for anyone else.', false, true),
  ('eng', 'long', 'But she went on all the same, shedding gallons of tears, until there was a large pool all round her, about four inches deep and reaching half down the hall.', false, true),
  ('eng', 'long', 'Laurie spoke very fast, and turned red and excited all in a minute, for he had kept his plot a secret, for fear of disappointing the girls or harming Beth.', false, true),
  ('eng', 'long', 'Moreover the grandmother was a keen old lady, and had all her five wits about her, and she knew what was going on in the house as soon as she entered it.', false, true),
  ('eng', 'long', 'If you will kill for me the Wicked Witch of the West, I will bestow upon you a great many brains, and such good brains that you will be the wisest man in all the Land of Oz.', false, true),
  ('eng', 'long', 'All he thinks he has a right to when he comes to you to be yours is fairness. After you have been unfair to him he will love you again, but will never afterwards be quite the same boy.', false, true),
  ('eng', 'long', 'Come, cheer up, Toady! There are more ways of getting back a place than taking it by storm. I haven’t said my last word yet. Now I’m going to tell you a great secret.', false, true),
  ('eng', 'long', 'Mrs. Bennet treasured up the hint, and trusted that she might soon have two daughters married; and the man whom she could not bear to speak of the day before, was now high in her good graces.', false, true),
  ('eng', 'long', 'I guess you’re all right at anything. Mr. Phillips told me last week in Blair’s store at Carmody that you was the smartest scholar in school and was making rapid progress.', false, true),
  ('eng', 'long', 'Mrs. Sowerby laughed so heartily at the revelation of this difficulty that she quite rocked backward and forward in her blue cloak, and Dickon laughed with her.', false, true),
  ('eng', 'long', 'And yet I wish I could show you our cat Dinah: I think you’d take a fancy to cats if you could only see her. We won’t talk about her any more if you’d rather not.', false, true),
  ('eng', 'long', 'I like to please Laurie, and I’m not afraid of Mr. Brooke, he is so kind. But I don’t want to play, or sing, or say anything. I’ll work hard and not trouble anyone, and you’ll take care of me, Jo, so I’ll go.', false, true),
  ('eng', 'long', 'The doctor laid his hand on her and tried to calm her excitement. But hear now what I have to ask you. If I am ever ill and alone, will you come then and stay with me?', false, true),
  ('eng', 'long', 'Well, in a few minutes I shall be all melted, and you will have the castle to yourself. I have been wicked in my day, but I never thought a little girl like you would ever be able to melt me and end my wicked deeds.', false, true),
  ('eng', 'long', 'None of them knew. Perhaps it was best not to know. Their ignorance gave them one more glad hour; and as it was to be their last hour on the island, let us rejoice that there were sixty glad minutes in it.', false, true),
  ('eng', 'long', 'I was indeed hungry when I sat down, and ever since I inadvertently happened to mention shell-fish, my pangs have been extreme. But couldn’t you fetch it along out here?', false, true),
  ('eng', 'long', 'The turn of your countenance I shall never forget, as you said that I could not have addressed you in any possible way that would induce you to accept me.', false, true),
  ('eng', 'long', 'We’re not talking about poetry, Anne--we are talking about saying your prayers. Don’t you know it’s a terrible wicked thing not to say your prayers every night?', false, true),
  ('eng', 'long', 'It was a massive door and opened into a big bedroom. There were embroidered hangings on the wall, and inlaid furniture such as she had seen in India stood about the room.', false, true),
  ('eng', 'long', 'And she’s such a capital one for catching mice you can’t think! And oh, I wish you could see her after the birds! Why, she’ll eat a little bird as soon as look at it!', false, true),
  ('eng', 'long', 'The lunch looked charming, and as she surveyed it, she sincerely hoped it would taste well, and that the borrowed glass, china, and silver would get safely home again.', false, true),
  ('eng', 'long', 'In her eagerness to obtain what she had set her heart upon Heidi hardly gave herself time to get out all she had to say, and did not pause for breath till she reached the end of her sentence.', false, true),
  ('eng', 'long', 'After picking out the silver shoe, which was all that was left of the old woman, she cleaned and dried it with a cloth, and put it on her foot again.', false, true),
  ('eng', 'long', 'Then John was born, with the extra pomp that he conceived due to the birth of a male, and Michael came from his bath to ask to be born also, but John said brutally that they did not want any more.', false, true),
  ('eng', 'long', 'At last, cold, hungry, and tired out, he sought the shelter of a hollow tree, where with branches and dead leaves he made himself as comfortable a bed as he could, and slept soundly till the morning.', false, true),
  ('eng', 'long', 'But here, by carrying with me one ceaseless source of regret in my sister’s absence, I may reasonably hope to have all my expectations of pleasure realized.', false, true),
  ('eng', 'long', 'Very different this from the plain benches at the Debating Club, filled with the homely, sympathetic faces of friends and neighbors. These people, she thought, would be merciless critics.', false, true),
  ('eng', 'long', 'Once she crept into the dining-room and found it empty, though a partly finished meal was on the table and chairs and plates looked as if they had been hastily pushed back when the diners rose suddenly for some reason.', false, true),
  ('eng', 'long', 'I think it very appropriate to you, and feel very grateful for your efforts to make it so pretty, but we must give up our private wishes, of course, and I will see that you have a good place elsewhere.', false, true),
  ('eng', 'long', 'Herr Sesemann stood still for a while to let the cool Alpine wind blow on his hot face. But now some one came running down the mountain- side--it was Peter with the telegram in his hand.', false, true),
  ('eng', 'long', 'So, carefully and gently, they lifted Dorothy in their arms and carried her swiftly through the air until they came to the castle, where they set her down upon the front doorstep.', false, true),
  ('eng', 'long', 'They are forbidden by Peter to look in the least like him, and they wear the skins of the bears slain by themselves, in which they are so round and furry that when they fall they roll.', false, true),
  ('eng', 'long', 'Perhaps he would never have dared to raise his eyes, but that, though the piping was now hushed, the call and the summons seemed still dominant and imperious.', false, true),
  ('eng', 'long', 'That the Miss Lucases and the Miss Bennets should meet to talk over a ball was absolutely necessary; and the morning after the assembly brought the former to Longbourn to hear and to communicate.', false, true),
  ('eng', 'long', 'In a very short space of time Anne came flying back up the lane with tears rolling down her cheeks. Into the kitchen she dashed and flung herself face downward on the sofa in an agony.', false, true),
  ('eng', 'long', 'She carried the pepper-box in her hand, and Alice guessed who it was, even before she got into the court, by the way the people near the door began sneezing all at once.', false, true),
  ('eng', 'long', 'Shopping in Regent Street is perfectly splendid. Things seem so cheap, nice ribbons only sixpence a yard. I laid in a stock, but shall get my gloves in Paris.', false, true),
  ('eng', 'long', 'On the appointed night the two sat down and began at once to take some of the strengthening cordial, which at first made them very talkative and then very sleepy, so that they leant back in their seats and became silent.', false, true),
  ('eng', 'long', 'When she brought it into the Throne Room she spoke the magic words, and soon the band of Winged Monkeys flew in through the open window and stood beside her.', false, true),
  ('eng', 'long', 'Their ignorance gave them one more glad hour; and as it was to be their last hour on the island, let us rejoice that there were sixty glad minutes in it.', false, true),
  ('eng', 'long', 'Toad sat straight down in the middle of the dusty road, his legs stretched out before him, and stared fixedly in the direction of the disappearing motor-car.', false, true),
